function initProduct(){for(const ws of state.workspaces){if(!ws.product){const demo=ws.id==='demo';ws.product={projects:demo?structuredClone(demoProjects):[],clients:demo?structuredClone(demoClients):[],tasks:demo?structuredClone(demoTasks):[],invoices:demo?structuredClone(demoInvoices):[],expenses:demo?structuredClone(demoExpenses):[],investments:demo?structuredClone(demoInvestments):[],notes:demo?structuredClone(demoNotes):[],meetings:demo?structuredClone(demoMeetings):[],events:demo?structuredClone(demoEvents):[],budgets:demo?[{id:'b0',title:'April 2025',date:'2025-04-01',amount:100000,categories:structuredClone(categories),carry:true,alert:'80%',notes:''}]:[]};if(!demo){for(const t of ws.data.tasks||[])ws.product.tasks.push({id:'t'+Date.now()+Math.random(),title:t[0],client:t[1],project:t[2],priority:t[3],status:t[4]?'Done':'Todo',date:'Today',subtasks:[],done:[],attachments:[],comments:[]})}}}save()}
initProduct();
const db=()=>state.workspaces.find(w=>w.id===state.current).product;
let selectedRecord={Projects:'p0',Clients:'c0',Tasks:'t0',Invoices:'i0',Expenses:'e2',Notes:'n0',Meetings:'m0',Calendar:'ev7'},viewMode={},activeTab={},filters={},editorState=null;
const pageKey={Projects:'projects',Clients:'clients',Tasks:'tasks',Invoices:'invoices',Expenses:'expenses',Notes:'notes',Meetings:'meetings',Investments:'investments',Budget:'budgets',Calendar:'events'};
const entity={Projects:'Project',Clients:'Client',Tasks:'Task',Invoices:'Invoice',Expenses:'Expense',Notes:'Note',Meetings:'Meeting',Investments:'Investment',Budget:'Budget',Calendar:'Event'};
const fmtDate=d=>!d?'—':d==='Today'?'Today':new Date((d.length===7?d+'-01':d)+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const shortDate=d=>!d?'—':d==='Today'?'Today':new Date((d.length===7?d+'-01':d)+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const timeFmt=t=>{if(!t)return '11:00 AM';let [h,m]=t.split(':');return (+h%12||12)+':'+m+(+h<12?' AM':' PM')};
function pill(text){const cls={'In Progress':'sent',Active:'paid',Confirmed:'paid',Completed:'purple',Planned:'sent',Sent:'sent',Paid:'paid',Todo:'neutral',Done:'paid','On Hold':'medium',Overdue:'medium','Partially Paid':'purple',Cancelled:'high',High:'high',Medium:'medium',Low:'low',Advisor:'purple',Client:'sent',Internal:'paid',CA:'high',Bank:'high','Mutual Fund':'sent',Stock:'paid',FD:'purple',Gold:'medium',Bond:'high',Reimbursable:'sent'}[text]||'neutral';return `<span class="badge ${cls}">${esc(text||'—')}</span>`}
function logoFor(name){return db().clients.find(c=>c.title===name)?.logo||db().projects.find(p=>p.title===name)?.logo||'internal'}
function logoMark(kind='internal',size=''){const labels={nova:'N',square:'▣',bright:'♧',gear:'G6',r2:'R2',internal:'Ii',creative:'◕',landing:'◈',system:'◒',mobile:'◐',pitch:'◢',figma:'F',google:'G',domain:'↔'};return `<span class="brand mark ${kind} ${size}">${labels[kind]||(!['pixel'].includes(kind)?icon(kind):'')}</span>`}
function nameCell(title,sub,logo){return `<div class="name-cell">${logoMark(logo)}<div><strong>${esc(title)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</div></div>`}
function btn(label,fn,cls=''){return action(label,fn,cls)}
const ib=(name,fn,label=name)=>`<button class="icon-btn" title="${label}" aria-label="${label}" onclick="${fn}">${icon(name)}</button>`;
function rowLine(label,value,ico){return `<div class="meta-row">${ico?icon(ico):''}<span>${label}</span><div>${value}</div></div>`}
function miniBars(color='#d5d5d9'){return `<span class="mini-bars">${[5,8,15,10,20,26,34].map(h=>`<i style="height:${h}px;background:${color}"></i>`).join('')}</span>`}
function kpis(items){return `<div class="stats reference-stats">${items.map(s=>`<section class="stat"><span class="stat-icon ${s[4]||''}">${icon(s[0])}</span><div><strong>${s[1]}</strong><p>${s[2]}</p><small class="${s[5]||'green'}">${isDemo()?(s[3]||''):''}</small></div>${isDemo()?miniBars(s[6]||'#d5d5d9'):''}</section>`).join('')}</div>`}
function pageHeader(title,subtitle,extra='',section=page){return `<header class="reference-header"><div><small>${section}</small><h1>${title}</h1><p>${subtitle}</p></div><div class="header-actions">${extra||btn(icon('plus')+' New '+entity[page],`startEditor('${page}')`,'primary')}${['Projects','Clients','Tasks','Invoices','Calendar','Meetings'].includes(page)?`<div class="segmented">${(page==='Calendar'?['Month','Week','Day','Agenda']:page==='Clients'?['List','Cards']:page==='Tasks'?['List','Board','Calendar']:page==='Invoices'?['List','Kanban']:page==='Meetings'?['List','Calendar']:['List','Board']).map(v=>btn((v==='List'?icon('list'):v==='Board'||v==='Cards'?icon('board'):'')+v,`setView('${v}')`,(viewMode[page]|| (page==='Calendar'?'Week':'List'))===v?'active':'')).join('')}</div>`:''}${ib('more','pageMenu(event)','More options')}</div></header>`}
function tabs(items){if(!isDemo())items=items.map(([t,count])=>[t,count===undefined?undefined:t==='All'?db()[pageKey[page]].length:db()[pageKey[page]].filter(r=>r.status===t||r.category===t||r.date===t).length]);let active=activeTab[page]||items[0][0];return `<div class="reference-tabs">${items.map(([t,count])=>btn(esc(t)+(count!==undefined?` <small>${count}</small>`:''),`setTab('${t}')`,active===t?'active':'')).join('')}</div>`}
function filterBar(options){return `<div class="filter-bar"><label class="input-search">${icon('search')}<input aria-label="Search ${page}" placeholder="Search ${page.toLowerCase()}..." value="${esc(filters.search||'')}" oninput="setFilter('search',this.value)"></label>${options.map(([label,field,values])=>`<select aria-label="${label}" onchange="setFilter('${field}',this.value)"><option value="">${label}</option>${[...new Set(values)].filter(v=>v!==undefined&&v!==null&&v!=='').map(v=>`<option ${filters[field]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`).join('')}${btn('Clear','clearFilters()','text-button')}</div>`}
function records(){let rows=db()[pageKey[page]]||[];const tab=activeTab[page];return rows.filter(r=>Object.entries(filters).every(([k,v])=>!v||(k==='search'?[r.title,r.client,r.project,r.category,r.type].filter(Boolean).join(' ').toLowerCase().includes(v.toLowerCase()):String(r[k])===v))).filter(r=>!tab||tab==='All'||tab==='All Notes'||tab==='Today'&&r.date==='Today'||tab==='Upcoming'&&r.status!=='Done'||tab==='Overdue'&&r.date!=='Today'&&r.date<'2025-04-28'||tab==='Completed'&&['Completed','Done'].includes(r.status)||r.status===tab||r.category===tab||r.type===tab||tab==='Advisors'&&r.type==='Advisor'||tab==='Clients'&&r.type==='Client')}
function selected(){return db()[pageKey[page]]?.find(r=>r.id===selectedRecord[page])}
function table(headers,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr><th><input class="check" type="checkbox" aria-label="Select all rows" onchange="selectAllRows(this.checked)"></th>${headers.map(h=>`<th>${h}</th>`).join('')}<th>${icon('more')}</th></tr></thead><tbody>${rows||`<tr><td colspan="12"><div class="empty">No matching ${page.toLowerCase()}. ${btn('Create '+entity[page],`startEditor('${page}')`)}</div></td></tr>`}</tbody></table></div>`}
function tableRow(r,cells){return `<tr class="${selectedRecord[page]===r.id?'selected':''}" data-record="${r.id}" onclick="selectRecord('${r.id}')"><td><input class="check" aria-label="Select ${esc(r.title)}" type="checkbox" ${r.selected?'checked':''} onclick="event.stopPropagation()" onchange="selectRow('${r.id}',this.checked)"></td>${cells.map(c=>`<td>${c}</td>`).join('')}<td>${ib('more',`event.stopPropagation();recordMenu(event,'${r.id}')`,'Record actions')}</td></tr>`}
const originals={render,navigate,openQuick,createWorkspace,switchWorkspace,detail,dashboard};
render=function(){originals.render();if(!editorState&&page==='Today')return;document.querySelector('.shell').className='shell product-shell '+(editorState?'editor-shell':page.toLowerCase()+'-shell');document.querySelector('.shell').innerHTML=editorState?editorPage():productPage();document.querySelectorAll('nav button').forEach((b,i)=>b.classList.toggle('active',navs[i]===page));};
navigate=function(p){page=p;editorState=null;filters={};window.detailTab='Overview';render();window.scrollTo(0,0)};
function setView(v){viewMode[page]=v;render()}function setTab(t){activeTab[page]=t;render()}function setFilter(k,v){filters[k]=v;const pos=document.querySelector('.input-search input')?.selectionStart;render();if(k==='search'){let inp=document.querySelector('.input-search input');inp?.focus();inp?.setSelectionRange(pos,pos)}}function clearFilters(){filters={};render()}function selectRecord(id){selectedRecord[page]=id;render()}function closeInspector(){selectedRecord[page]=null;render()}function selectRow(id,v){let r=db()[pageKey[page]].find(r=>r.id===id);r.selected=v;save()}function selectAllRows(v){records().forEach(r=>r.selected=v);save();render()}
function splitPage(content,inspector){return `<main class="reference-main">${content}</main>${inspector?`<section class="inspector">${inspector}</section>`:''}`}
function inspectorTop(){return `<div class="inspector-actions">${ib('more','recordMenu(event,selectedRecord[page])','More actions')}${ib('close','closeInspector()','Close details')}</div>`}
function inspectorTabs(items){return `<div class="inspector-tabs">${items.map(t=>btn(t,`inspectorTab('${t}')`,(window.detailTab||'Overview')===t?'active':'')).join('')}</div>`}
function productPage(){if(!isDemo()&&!db()[pageKey[page]]?.length)return `<main class="reference-main">${pageHeader(page==='Budget'?'Monthly Budget':page==='Calendar'?'Calendar':'All '+page,'')}<section class="reference-box"><div class="empty">${icon(icons[navs.indexOf(page)]||'folder')}<h3>No ${page.toLowerCase()} yet</h3><p>Create your first ${entity[page].toLowerCase()} to get started.</p>${btn('+ New '+entity[page],`startEditor('${page}')`,'primary')}</div></section></main>`;switch(page){case'Projects':return projectsPage();case'Clients':return clientsPage();case'Tasks':return tasksPage();case'Invoices':return invoicesPage();case'Expenses':return expensesPage();case'Budget':return budgetPage();case'Investments':return investmentsPage();case'Notes':return notesPage();case'Meetings':return meetingsPage();case'Calendar':return calendarPage();default:return ''}}
function projectsPage(){const p=selected(),rows=records();return splitPage(pageHeader('All Projects','Plan, track and deliver your work.')+kpis([['folder',db().projects.filter(r=>r.status==='Active').length,'Active projects','↑ 50%'],['check',db().projects.filter(r=>r.status==='Completed').length,'Completed','↑ 100%'],['clock',metric('18h 30m','0h 00m'),'Total tracked time','↑ 12%'],['money',money(metric(240000,db().projects.reduce((n,p)=>n+p.amount,0))),'Total project value','↑ 28%']])+`<section class="reference-box">${tabs(['All','Active','Planned','On Hold','Completed','Archived'].map(t=>[t,t==='All'?db().projects.length:db().projects.filter(r=>r.status===t).length]))}${filterBar([['Client','client',db().clients.map(c=>c.title)],['Status','status',['Active','Planned','On Hold','Completed']],['Priority','priority',['High','Medium','Low']],['Category','category',db().projects.map(p=>p.category)]])}${viewMode.Projects==='Board'?boardView(rows,'status',['Planned','Active','On Hold','Completed']):table(['Project','Client','Status','Progress','Deadline','Budget','Tracked'],rows.map(r=>tableRow(r,[nameCell(r.title,r.category,r.logo),nameCell(r.client,'',logoFor(r.client)),pill(r.status),`<div class="inline-progress"><span>${r.progress}%</span><div class="progress"><i style="width:${r.progress}%"></i></div></div>`,fmtDate(r.date),money(r.amount),r.tracked])).join(''))}</section>`,p?projectInspector(p):'')}
function projectInspector(p){return inspectorTop()+`<div class="inspector-identity">${logoMark(p.logo)}<div><h2>${esc(p.title)}</h2><p>${esc(p.client)} ・ ${esc(p.category)}</p>${statusSelect(p,['Active','Planned','On Hold','Completed','Archived'])}</div></div>`+inspectorTabs(['Overview','Tasks','Time','Invoices','Notes'])+detailTabContent(p,()=>`<div class="detail-section"><div class="panel-head"><h3>Progress</h3><span>${p.progress}%</span></div><input class="progress-range" aria-label="Project progress" type="range" value="${p.progress}" oninput="updateRecord('progress',+this.value)"><div class="detail-kpis"><div>${icon('clock')}<strong>${p.tracked}</strong><small>Total time</small></div><div>${icon('money')}<strong>${money(p.amount)}</strong><small>Project budget</small></div></div>${rowLine('Start date',fmtDate(p.start),'calendar')}${rowLine('Deadline',fmtDate(p.date),'calendar')}${rowLine('Client',esc(p.client),'users')}${rowLine('Project manager','Designer (You)','user')}${rowLine('Category',pill(p.category),'folder')}${rowLine('Priority',pill(p.priority),'flag')}</div><div class="detail-section"><div class="panel-head"><h3>Description</h3>${btn('Edit',"editText('description')",'small-button')}</div><p>${esc(p.description)}</p></div><div class="detail-section"><div class="panel-head"><h3>Links</h3>${btn('Edit',"editLinks()",'small-button')}</div>${rowLine('Figma file','<a href="https://figma.com" target="_blank" rel="noopener">https://figma.com/…</a>','file')}${rowLine('Project brief','<a href="https://drive.google.com" target="_blank" rel="noopener">https://drive.google.com/…</a>','file')}${rowLine('Live site (draft)','<a href="https://staging.pixelstudio.com" target="_blank" rel="noopener">https://staging.pixelstudio.com</a>','link')}</div><div class="detail-section">${sectionHead('Deliverables',"addChecklist('deliverables')")}${checklist(p,'deliverables')}</div>`)}
function clientsPage(){const c=selected();return splitPage(pageHeader('All Clients','Manage your clients, track projects, invoices and build long-term relationships.')+kpis([['users',metric(6,db().clients.length),'Total clients','↑ 20%'],['briefcase',metric(3,db().clients.filter(c=>c.status==='Active').length),'Active clients','↑ 50%'],['file',metric(8,db().projects.length),'Total projects','↑ 33%'],['money',money(metric(485000,db().clients.reduce((n,c)=>n+c.amount,0))),'Total billed','↑ 28%']])+`<section class="reference-box">${filterBar([['Status','status',['Active','On Hold','Completed']],['Country','country',['India','USA','UAE']],['Industry','industry',db().clients.map(c=>c.industry)]])}${viewMode.Clients==='Cards'?`<div class="record-cards">${records().map(r=>`<button class="record-card" onclick="selectRecord('${r.id}')">${nameCell(r.title,r.industry,r.logo)}${pill(r.status)}<p>${r.projects} projects · ${money(r.amount)}</p></button>`).join('')}</div>`:table(['Client','Status','Projects','Total Billed','Outstanding','Country','Added'],records().map(r=>tableRow(r,[nameCell(r.title,r.industry,r.logo),pill(r.status),r.projects,money(r.amount),`<span class="${r.outstanding?'red':''}">${money(r.outstanding)}</span>`,(r.country==='India'?'🇮🇳':r.country==='USA'?'🇺🇸':'🇦🇪')+' &nbsp; '+r.country,fmtDate(r.date)])).join(''))}</section>`,c?clientInspector(c):'')}
function clientInspector(c){return inspectorTop()+`<div class="inspector-identity">${logoMark(c.logo)}<div><h2>${esc(c.title)}</h2><p>${esc(c.industry)} ・ ${c.country}</p>${statusSelect(c,['Active','On Hold','Completed'])}</div></div>`+inspectorTabs(['Overview','Projects','Invoices','Meetings','Notes'])+detailTabContent(c,()=>`<div class="detail-card">${rowLine('Email',`<a href="mailto:${esc(c.email)}">${esc(c.email)}</a>`,'mail')}${rowLine('Phone',esc(c.phone),'phone')}${rowLine('Website',`<a href="${esc(c.website)}" target="_blank" rel="noopener">${esc(c.website)}</a>`,'link')}${rowLine('Location',esc(c.location),'location')}${rowLine('Industry',esc(c.industry),'briefcase')}${rowLine('Added',fmtDate(c.date),'calendar')}</div><div class="detail-kpis client-kpis">${[[c.projects,'Projects','folder'],[money(c.amount),'Total billed','money'],[money(c.outstanding),'Outstanding','shield'],[money(c.amount-c.outstanding),'Received','wallet']].map(v=>`<div>${icon(v[2])}<strong>${v[0]}</strong><small>${v[1]}</small></div>`).join('')}</div><div class="detail-card"><h3>Recent projects</h3>${db().projects.filter(p=>p.client===c.title).map(p=>`<button class="related-row" onclick="goRecord('Projects','${p.id}')">${nameCell(p.title,p.category,p.logo)}${pill(p.status)}</button>`).join('')||'<p>No projects yet</p>'}</div><div class="detail-card"><h3>Recent invoices</h3>${db().invoices.filter(i=>i.client===c.title).map(i=>`<button class="related-row" onclick="goRecord('Invoices','${i.id}')">${i.title}<span>${money(i.amount)}</span>${pill(i.status)}</button>`).join('')}</div><div class="detail-card"><h3>Latest activity</h3><p>✓ Invoice INV-004 marked as paid <small>2 days ago</small></p><p>Meeting scheduled: Design review</p><p>Project Website Redesign updated</p></div>`)}
function tasksPage(){const t=selected();return splitPage(pageHeader('All Tasks','Stay focused and get your work done.')+kpis([['check',metric(4,db().tasks.filter(t=>t.date==='Today').length),'Tasks today','2 completed'],['clock',metric(12,db().tasks.filter(t=>t.date!=='Today'&&t.date<'2025-04-28'&&t.status!=='Done').length),'Overdue','↑ 3','','red'],['calendar',metric(18,db().tasks.filter(t=>t.date>'2025-04-28').length),'Upcoming','Next 7 days','','muted'],['target',metric(32,db().tasks.filter(t=>t.status==='Done').length),'Completed','This month','','muted','#a3e9c4']])+`<section class="reference-box">${tabs([['All',46],['Today',4],['Overdue',12],['Upcoming',18],['Completed',32]])}${filterBar([['Project','project',db().projects.map(p=>p.title)],['Client','client',db().clients.map(c=>c.title)],['Status','status',['Todo','In Progress','Review','Blocked','Done']],['Priority','priority',['High','Medium','Low']]])}${viewMode.Tasks==='Board'?boardView(records(),'status',['Todo','In Progress','Done']):viewMode.Tasks==='Calendar'?weekGrid(true):table(['Task','Project','Client','Due date','Priority','Status'],records().map(r=>tableRow(r,[`<span>${esc(r.title)}</span> ${['t0','t1','t4'].includes(r.id)?'<small class="muted"> ▢ '+(r.id==='t4'?5:3)+'</small>':''}`,nameCell(r.project,'',logoFor(r.project)),r.client==='—'?'—':nameCell(r.client,'',logoFor(r.client)),`<span class="${r.date==='Today'?'red':'muted'}">${fmtDate(r.date)}</span>`,pill(r.priority),pill(r.status)])).join(''))}</section>`,t?taskInspector(t):'')}
function taskInspector(t){return inspectorTop()+`<h2 class="task-inspector-title">${esc(t.title)}</h2><div class="status-pair">${statusSelect(t,['Todo','In Progress','Review','Blocked','Done'])}${prioritySelect(t)}</div><div class="detail-section">${rowLine('Project',nameCell(t.project,'',logoFor(t.project)),'folder')}${rowLine('Client',nameCell(t.client,'',logoFor(t.client)),'users')}${rowLine('Due date',fmtDate(t.date),'calendar')}${rowLine('Estimated time',esc(t.estimated||'—'),'clock')}${rowLine('Tracked time',esc(t.tracked||'0h'),'clock')}${rowLine('Repeat',esc(t.repeat||'Does not repeat'),'repeat')}${rowLine('Category',esc(t.category||'Design'),'folder')}${rowLine('Assignee','You','user')}</div><div class="detail-section"><div class="panel-head"><h3>Description</h3>${btn('Edit',"editText('description')",'small-button')}</div><p>${esc(t.description||'')}</p></div><div class="detail-section">${sectionHead('Subtasks <small>'+((t.done||[]).length)+' / '+(t.subtasks||[]).length+'</small>',"addChecklist('subtasks')")}${checklist(t,'subtasks')}</div><div class="detail-section">${sectionHead('Attachments',"uploadToSelected()")}${attachments(t)}</div><div class="detail-section"><h3>Comments <small>${(t.comments||[]).length}</small></h3>${(t.comments||[]).map(c=>`<div class="comment"><span class="avatar">RY</span><div><strong>${esc(c.name)} <small>${esc(c.time)}</small></strong><p>${esc(c.text)}</p></div></div>`).join('')}<form onsubmit="addComment(event)"><input class="simple-input" name="comment" placeholder="Add a comment..." required><button class="icon-btn" title="Send comment">${icon('send')}</button></form></div>`}
function sectionHead(title,fn){return `<div class="panel-head"><h3>${title}</h3>${btn('+ Add',fn,'small-button')}</div>`}
function checklist(r,key){return (r[key]||[]).map((s,i)=>`<label class="checklist-row"><input class="check" type="checkbox" ${(r.done||[]).includes(i)?'checked':''} onchange="toggleChecklist('${key}',${i},this.checked)"><span>${esc(s)}</span>${icon('grip')}</label>`).join('')}
function statusSelect(r,options){return `<select class="status-select ${['Active','Paid','Confirmed','Done'].includes(r.status)?'paid':r.status==='In Progress'?'sent':'neutral'}" aria-label="Status" onchange="updateRecord('status',this.value)">${options.map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select>`}
function prioritySelect(r){return `<select class="status-select high" aria-label="Priority" onchange="updateRecord('priority',this.value)">${['High','Medium','Low'].map(s=>`<option ${s===r.priority?'selected':''}>${s}</option>`).join('')}</select>`}
function detailTabContent(r,overview){const t=window.detailTab||'Overview';if(t==='Overview')return overview();if(t==='Time')return `<div class="detail-section"><h3>Time tracking</h3>${timer()}</div>`;const key={Projects:'projects',Tasks:'tasks',Invoices:'invoices',Meetings:'meetings',Notes:'notes'}[t];return `<div class="detail-section"><h3>${t}</h3>${key?(db()[key].filter(x=>x.client===r.title||x.project===r.title).map(x=>`<button class="related-row" onclick="goRecord('${t}','${x.id}')">${esc(x.title)}${icon('right')}</button>`).join('')||`<p>No linked ${t.toLowerCase()} yet.</p>`):'<p>No records yet.</p>'}</div>`}
function inspectorTab(t){window.detailTab=t;render()}function goRecord(p,id){page=p;selectedRecord[p]=id;window.detailTab='Overview';filters={};render()}
function boardView(rows,key,columns){return `<div class="kanban">${columns.map(c=>`<section class="kanban-column" ondragover="event.preventDefault()" ondrop="dropRecord(event,'${c}')"><h3>${c} <small>${rows.filter(r=>r[key]===c).length}</small></h3>${rows.filter(r=>r[key]===c).map(r=>`<article draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${r.id}')" onclick="selectRecord('${r.id}')"><strong>${esc(r.title)}</strong><p>${esc(r.client||r.project||'')}</p><footer>${pill(r.priority||r.status)}<span>${shortDate(r.date)}</span></footer></article>`).join('')}</section>`).join('')}</div>`}
function dropRecord(e,status){e.preventDefault();let r=db()[pageKey[page]].find(r=>r.id===e.dataTransfer.getData('text/plain'));if(r){r.status=status;save();render()}}
function updateRecord(key,value){let r=selected();if(r){r[key]=value;if(page==='Tasks'&&key==='status')r.isDone=value==='Done';syncDashboard();save();render()}}
function toggleChecklist(key,i,on){let r=selected();r.done=r.done||[];r.done=on?[...new Set([...r.done,i])]:r.done.filter(n=>n!==i);save();render()}
function addChecklist(key){textDialog('Add '+(key==='agenda'?'agenda item':key==='subtasks'?'subtask':'deliverable'),'Title','',value=>{let r=selected();(r[key]??=[]).push(value);save();render()})}
function addComment(e){e.preventDefault();let value=new FormData(e.target).get('comment').trim();if(!value)return;let r=selected();(r.comments??=[]).push({name:'You',text:value,time:'Just now'});save();render()}
function editText(key){textDialog('Edit '+key,key,selected()[key]||'',value=>updateRecord(key,value),true)}
function textDialog(title,label,value,callback,multiline=false){window.dialogCallback=callback;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal small-modal" role="dialog" aria-modal="true"><header><h2>${title}</h2>${ib('close','closeOverlay()')}</header><form onsubmit="event.preventDefault();const v=this.elements.value.value.trim();if(v){closeOverlay();window.dialogCallback(v)}"><label class="field">${label}${multiline?`<textarea name="value" required>${esc(value)}</textarea>`:`<input name="value" value="${esc(value)}" required>`}</label><footer>${btn('Cancel','closeOverlay()')}<button class="primary" type="submit">Save</button></footer></form></section></div>`;document.querySelector('.small-modal [name=value]').focus()}
function recordMenu(e,id){e?.stopPropagation();document.querySelector('.context-menu')?.remove();let el=document.createElement('div');el.className='context-menu';const rect=e?.currentTarget?.getBoundingClientRect();el.style.top=Math.min(rect?.bottom||70,innerHeight-270)+'px';el.style.left=Math.min(rect?.left||innerWidth-230,innerWidth-230)+'px';el.innerHTML=[['edit','Edit',`editRecord('${id}')`],['copy','Duplicate',`duplicateRecord('${id}')`],['check','Mark as completed',`completeRecord('${id}')`],['trash','Delete',`removeRecord('${id}')`]].map(([ico,t,fn])=>btn(icon(ico)+t,`document.querySelector('.context-menu')?.remove();${fn}`,ico==='trash'?'red':'')).join('');document.body.append(el)}
function pageMenu(e){recordMenu(e,selectedRecord[page])}
function editRecord(id){let r=db()[pageKey[page]].find(r=>r.id===id);if(r)startEditor(page,r)}
function duplicateRecord(id){let r=db()[pageKey[page]].find(r=>r.id===id);if(r){let copy=structuredClone(r);copy.id='r'+Date.now();copy.title+=' (copy)';db()[pageKey[page]].push(copy);save();render();toast('Record duplicated')}}
function completeRecord(id){let r=db()[pageKey[page]].find(r=>r.id===id);if(r){r.status=page==='Tasks'?'Done':page==='Invoices'?'Paid':'Completed';save();render()}}
function removeRecord(id){let key=pageKey[page];let r=db()[key].find(r=>r.id===id);if(!r)return;db()[key]=db()[key].filter(r=>r.id!==id);selectedRecord[page]=db()[key][0]?.id;syncDashboard();save();render();toast('Record deleted')}
function editLinks(){textDialog('Project link','URL',selected().link||'',v=>updateRecord('link',v))}
function attachments(r){return (r.attachments||[]).map((a,i)=>`<div class="attachment-row">${logoMark(a.kind==='PDF'?'file':a.kind==='Figma'?'figma':'attach','small')}<div><strong>${esc(a.name)}</strong><small>${esc(a.size||'')} · ${fmtDate(a.date||'2025-04-25')}</small></div>${ib('download',`downloadAttachment(${i})`,'Download attachment')}${ib('trash',`removeAttachment(${i})`,'Remove attachment')}</div>`).join('')}
function uploadToSelected(){chooseFiles(files=>{let r=selected();r.attachments??=[];r.attachments.push(...files);save();render()})}
function chooseFiles(callback){const input=document.createElement('input');input.type='file';input.multiple=true;input.onchange=async()=>{let files=[];for(const f of input.files){if(f.size>10*1024*1024){toast(f.name+' exceeds 10 MB');continue}try{files.push(await window.MonoFiles.put(f))}catch(error){toast('File could not be stored. Check available browser storage.')}}callback(files)};input.click()}
async function downloadAttachment(i){const file=selected().attachments[i];const url=await window.MonoFiles.url(file);if(url){const a=document.createElement('a');a.href=url;a.download=file.name;a.click()}else toast('This is a sample attachment. Upload a file to enable download.')}
function removeAttachment(i){selected().attachments.splice(i,1);save();render()}
function invoicesPage(){const i=selected();return splitPage(pageHeader('All Invoices','Create and manage invoices, track payments and get paid on time.')+kpis([['calendar',money(metric(485000,db().invoices.reduce((n,r)=>n+r.amount,0))),'Total invoiced','↑ 28%'],['calendar',money(metric(180000,db().invoices.filter(r=>r.status==='Paid').reduce((n,r)=>n+r.amount,0))),'Received','↑ 42%','','green','#a4edc7'],['shield',money(metric(60000,db().invoices.filter(r=>r.status!=='Paid').reduce((n,r)=>n+r.amount,0))),'Outstanding','↓ 12%','','red'],['clock',metric(12,db().tasks.filter(t=>t.date!=='Today'&&t.date<'2025-04-28'&&t.status!=='Done').length),'Overdue','↑ 3','','red','#ffa0a9']])+`<section class="reference-box">${filterBar([['Status','status',['Paid','Sent','Overdue','Partially Paid','Draft','Cancelled']],['Client','client',db().clients.map(c=>c.title)],['Project','project',db().projects.map(p=>p.title)]])}${viewMode.Invoices==='Kanban'?boardView(records(),'status',['Draft','Sent','Paid','Overdue']):table(['Invoice','Client','Project','Issue date','Due date','Amount','Status'],records().map(r=>tableRow(r,[`<span class="invoice-number">${icon('invoice')}${esc(r.title)}</span>`,nameCell(r.client,db().clients.find(c=>c.title===r.client)?.industry||'',logoFor(r.client)),esc(r.project),fmtDate(r.date),`<span class="${r.status==='Overdue'?'red':''}">${fmtDate(r.due)}</span>`,money(r.amount),pill(r.status)])).join(''))}</section>`,i?invoiceInspector(i):'')}
function invoicePaper(i,compact=false){let subtotal=i.items?.reduce((n,item)=>n+item.qty*item.rate,0)||i.amount,total=subtotal*(1+(i.tax||0)/100);return `<article class="invoice-paper ${compact?'compact':''}"><header><div class="logo">mono.</div><div><h3>INVOICE</h3><small>${esc(i.title)}</small><small>${fmtDate(i.date)}</small></div></header><div class="invoice-address"><div><small>From</small><strong>Raman Yadav</strong><p>Thane, Maharashtra, India<br>ramandesign9@gmail.com<br>+91 98765 43210</p></div><div><small>Bill To</small><strong>${esc(i.client)}</strong><p>${esc(db().clients.find(c=>c.title===i.client)?.industry||'Design Agency')}<br>Mumbai, India<br>hello@pixelstudio.in</p></div></div>${!compact?`<div class="invoice-dates"><div><small>Invoice Date</small><p>${fmtDate(i.date)}</p></div><div><small>Due Date</small><p>${fmtDate(i.due)}</p></div><div><small>Amount Due</small><strong>${money(total)}</strong></div></div>`:''}<table><thead><tr><th>Item</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${(i.items||[]).map(item=>`<tr><td>${esc(item.title)}<small>${esc(item.description||'')}</small></td><td>${item.qty}</td><td>${money(item.rate)}</td><td>${money(item.qty*item.rate)}</td></tr>`).join('')}</tbody></table><div class="invoice-totals"><p><span>Subtotal</span><strong>${money(subtotal)}</strong></p><p><span>Tax (${i.tax||0}%)</span><strong>${money(total-subtotal)}</strong></p><p><b>Total${compact?'':' (INR)'}</b><strong>${money(total)}</strong></p></div>${!compact?`<div class="invoice-footer"><div><h4>${icon('bank')} Payment Instructions</h4><p>Bank Name <b>HDFC Bank</b></p><p>Account Name <b>Raman Yadav</b></p><p>Account Number <b>1234 5678 9012</b></p><p>IFSC Code <b>HDFC0001234</b></p></div><div><h4>Notes</h4><p>${esc(i.notes||'')}</p></div></div>`:''}</article>`}
function invoiceInspector(i){return inspectorTop()+`<div class="invoice-inspector-title"><h2>${i.title}</h2>${statusSelect(i,['Draft','Sent','Paid','Partially Paid','Overdue','Cancelled'])}</div><p>Issued ${fmtDate(i.date)} · Due ${fmtDate(i.due)}</p>${inspectorTabs(['Overview','Payments','Activity','Notes'])}${(window.detailTab||'Overview')==='Overview'?`<div class="detail-card invoice-preview-card">${invoicePaper(i,true)}<div class="paid-line">${pill(i.status)} <small>${i.status==='Paid'?'Paid on 25 Apr 2025':'Payment pending'}</small><strong>${money(i.amount)}</strong></div><div class="button-row">${btn(icon('download')+' Download PDF',"printInvoice()",'primary')}${btn(icon('send')+' Send',"sendInvoice()")}${btn(icon('edit')+' Edit',`editRecord('${i.id}')`)}</div></div><div class="detail-card"><h3>Client</h3>${nameCell(i.client,'Design Agency ・ Mumbai, India',logoFor(i.client))}</div><div class="detail-card"><h3>Project</h3>${nameCell(i.project,'Active',logoFor(i.project))}</div><div class="detail-card">${sectionHead('Payment history',"addPayment()")}${(i.payments||[]).map(p=>`<div class="related-row"><div>${fmtDate(p.date)}<p>${p.method}</p></div><strong>${money(p.amount)}</strong></div>`).join('')||'<p>No payments recorded</p>'}</div><div class="detail-card"><h3>Notes</h3><p>${esc(i.notes||'')}</p></div>`:(window.detailTab==='Payments'?`<div class="detail-section">${sectionHead('Payments',"addPayment()")}${(i.payments||[]).map(p=>rowLine(fmtDate(p.date),money(p.amount),'wallet')).join('')}</div>`:window.detailTab==='Notes'?`<div class="detail-section">${btn('Edit notes',"editText('notes')")}<p>${esc(i.notes||'')}</p></div>`:'<div class="detail-section"><p>Invoice created '+fmtDate(i.date)+'</p><p>Status: '+i.status+'</p></div>')}`}
function printInvoice(){let i=editorState?.record||selected();let frame=document.createElement('iframe');frame.style.display='none';document.body.append(frame);frame.contentDocument.write('<html><head><title>'+esc(i.title)+'</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="product.css"></head><body>'+invoicePaper(i)+'</body></html>');frame.contentDocument.close();frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),1000)}}
function sendInvoice(){textDialog('Send invoice','Recipient email',db().clients.find(c=>c.title===(editorState?.record||selected()).client)?.email||'',email=>{let i=editorState?.record||selected();let href='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent('Invoice '+i.title)+'&body='+encodeURIComponent('Hello,\n\nPlease find invoice '+i.title+' for '+money(i.amount)+'.\nDue date: '+fmtDate(i.due)+'\n\nThank you,\nRaman Yadav');window.location.href=href;toast('Email composer opened. Review and send from your email app.')})}
function addPayment(){textDialog('Record payment','Amount received (₹)',String(selected().amount),value=>{let n=Number(value);if(!(n>0)){toast('Enter a valid amount');return}let r=selected();(r.payments??=[]).push({date:new Date().toISOString().slice(0,10),amount:n,method:'Bank Transfer'});r.status=r.payments.reduce((a,b)=>a+b.amount,0)>=r.amount?'Paid':'Partially Paid';save();render()})}
function expensesPage(){let e=selected();return splitPage(pageHeader('All Expenses','Track and manage your business expenses, receipts and reimbursements.',btn(icon('plus')+' Add Expense',"startEditor('Expenses')",'primary'))+kpis([['wallet',money(metric(124500,db().expenses.reduce((n,r)=>n+r.amount,0))),'Total Expenses','↑ 12%','','green','#98e8be'],['folder',money(metric(42300,db().expenses.filter(r=>r.date.startsWith('2025-04')).reduce((n,r)=>n+r.amount,0))),'This Month','↑ 8%','','red','#ffa5ac'],['pie',money(metric(28700,db().expenses.filter(r=>r.reimbursable).reduce((n,r)=>n+r.amount,0))),'Reimbursable','','','green','#92c7ff'],['file',metric(36,db().expenses.length),'Total Expenses','']])+`<section class="reference-box">${filterBar([['Category','category',db().expenses.map(e=>e.category)],['Project','project',db().projects.map(p=>p.title)],['Payment method','payment',['Cash','UPI','HDFC Card']]])}${table(['Date ↓','Description','Category','Project','Payment method','Amount','Status'],records().map(r=>tableRow(r,[fmtDate(r.date),nameCell(r.title,r.description,r.logo),pill(r.category),esc(r.project),`<span class="payment-method">${icon('wallet')}${r.payment}</span>`,money(r.amount),pill(r.status)])).join(''))}</section>`,e?expenseInspector(e):'')}
function expenseInspector(e){return `<div class="inspector-actions">${btn(icon('edit')+' Edit',`editRecord('${e.id}')`)}${ib('more',`recordMenu(event,'${e.id}')`)}</div><div class="expense-identity">${logoMark(e.logo)}<h2>${esc(e.title)} ${pill(e.status)}</h2><strong>${money(e.amount)}</strong><p>${fmtDate(e.date)}, ${timeFmt(e.time)}</p></div>${inspectorTabs(['Details','Receipt','Notes','Activity'])}${['Overview','Details'].includes(window.detailTab||'Overview')?`<div class="detail-card">${rowLine('Description',esc(e.title==='Client Meeting'?'Client meeting with R2A team at Cafe Coffee Day.':e.description))}${rowLine('Category',pill(e.category))}${rowLine('Project',nameCell(e.project,'Gaming Platform',logoFor(e.project)))}${rowLine('Client',esc(e.client))}${rowLine('Amount',money(e.amount))}${rowLine('Payment method',esc(e.payment))}${rowLine('Date & time',fmtDate(e.date)+', '+timeFmt(e.time))}${rowLine('Location',esc(e.location),'location')}${rowLine('Billable',switchControl(e.billable,"updateRecord('billable',this.checked)")+' <small>Mark as billable</small>')}${rowLine('Reimbursable',switchControl(e.reimbursable,"updateRecord('reimbursable',this.checked)")+' <small>Request reimbursement</small>')}${rowLine('Tags',(e.tags||[]).map(pill).join(' '))}</div><div class="detail-card"><h3>Receipt</h3>${receiptBlock(e,true)}</div><div class="detail-card"><div class="panel-head"><h3>Notes</h3>${ib('edit',"editText('notes')")}</div><p>${esc(e.notes||'')}</p></div>`:window.detailTab==='Receipt'?`<div class="detail-card">${receiptBlock(e)}</div>`:window.detailTab==='Notes'?`<div class="detail-section">${btn('Edit notes',"editText('notes')")}<p>${esc(e.notes||'')}</p></div>`:`<p>Expense recorded ${fmtDate(e.date)}.</p>`}`}
function switchControl(on,fn){return `<label class="switch"><input type="checkbox" ${on?'checked':''} onchange="${fn}"><span></span></label>`}
function receiptBlock(e,compact=false){return e.receipt?`<div class="receipt ${compact?'compact':''}"><img src="${e.receipt.url||''}" data-file-id="${e.receipt.id||''}" alt="Uploaded receipt"><span>${esc(e.receipt.name)}<small>${e.receipt.size}</small></span></div>`:`<button class="upload-zone ${compact?'compact':''}" onclick="uploadReceipt()">${icon('upload')}<strong>Upload Receipt</strong><small>JPG, PNG, PDF (max 10MB)</small></button>`}
function uploadReceipt(){chooseFiles(files=>{if(!files.length)return;let e=editorState?.record||selected();e.receipt=files[0];save();render()})}
function ringChart(total,label,values){let sum=values.reduce((n,v)=>n+v[1],0)||1,acc=0;let gradient=values.map(v=>{let start=acc;acc+=v[1]/sum*100;return `${v[2]} ${start}% ${acc}%`}).join(',');return `<div class="ring-chart" style="background:conic-gradient(${gradient||'#eee 0% 100%'})"><div><strong>${total}</strong><small>${label}</small></div></div>`}
function barChart(){let spent=[11,12,14,18,14,15,12,14,12,14,11,14],bud=[15,20,20,25,20,20,20,20,20,20,20,20];return `<div class="bar-chart"><div class="chart-labels"><span>₹30K</span><span>₹20K</span><span>₹10K</span><span>₹0</span></div><div class="chart-bars">${spent.map((n,i)=>`<div><section><i style="height:${bud[i]/30*100}%"></i><i style="height:${n/30*100}%" title="${money(n*1000)} spent"></i></section><small class="${i===3?'selected':''}">${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][i]}</small></div>`).join('')}</div></div>`}
function budgetPage(){const b=db().budgets[0]||{amount:0,categories:[]},cats=b.categories;return `<main class="finance-main">${pageHeader('Monthly Budget','Plan, track and stay in control of your business spending.',`<input type="month" aria-label="Budget month" value="${b.date?.slice(0,7)||'2025-04'}" onchange="changeBudgetMonth(this.value)">${btn(icon('plus')+' Add Budget',"startEditor('Budget')",'primary')}`)}${kpis([['wallet',money(b.amount),'Total Budget','↑ 12%','','green','#9be7c2'],['chart',money(cats.reduce((n,c)=>n+c[2],0)),'Total Spent','↑ 68%','','blue','#80b8ff'],['pie',money(b.amount-cats.reduce((n,c)=>n+c[2],0)),'Remaining','↑ 32%','','muted','#ff9fac'],['file',cats.length||0,'Budget Categories','']])}<section class="panel finance-chart"><div class="panel-head"><h2>${icon('pie')} Spending Overview</h2><div class="chart-legend"><span>● Budget</span><span class="blue-text">● Spent</span><select aria-label="Spending chart period" onchange="changeChartPeriod(this.value)"><option>Monthly</option><option>Weekly</option><option>Yearly</option></select></div></div>${cats.length?barChart():'<div class="empty">No spending data yet</div>'}</section><section class="panel budget-table"><h2>${icon('pie')} Category Budgets</h2><table class="data-table"><thead><tr>${['Category','Budget','Spent','Remaining','Progress',''].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${cats.map((c,i)=>`<tr><td>${nameCell(c[0],'',c[3])}</td><td>${money(c[1])}</td><td>${money(c[2])}</td><td>${money(c[1]-c[2])}</td><td><div class="budget-progress"><div class="progress"><i style="background:${c[4]};width:${Math.min(100,c[2]/c[1]*100)}%"></i></div><small>${Math.round(c[2]/c[1]*100)}%</small></div></td><td>${ib('more',`budgetCategoryMenu(${i})`)}</td></tr>`).join('')}</tbody></table>${btn(icon('plus')+' Add Category','addBudgetCategory()')}</section></main><section class="finance-side"><div class="panel allocation-panel"><div class="panel-head"><h2>This Month &nbsp; ${pill('On Track')}</h2>${ib('more',"startEditor('Budget',db().budgets[0])")}</div><div class="allocation-body">${ringChart(money(cats.reduce((n,c)=>n+c[2],0)),'Spent',cats.map(c=>[c[0],c[2],c[4]]))}<div class="allocation-legend">${cats.map(c=>`<div><i style="background:${c[4]}"></i><span>${c[0]}</span><strong>${money(c[2])}</strong><small>${Math.round(c[2]/(cats.reduce((n,c)=>n+c[2],0)||1)*100)}%</small></div>`).join('')}</div></div></div>${insights('budget')}<div class="panel recent-finance"><div class="panel-head"><h2>${icon('file')} Recent Expenses</h2>${btn('View All '+icon('arrow'),"navigate('Expenses')",'text-button')}</div>${db().expenses.slice(0,5).map(e=>`<button class="recent-row" onclick="goRecord('Expenses','${e.id}')">${nameCell(e.title,fmtDate(e.date),e.logo)}<strong>${money(e.amount)}</strong>${pill(e.category)}</button>`).join('')}</div></section>`}
function insights(type){let rows=type==='budget'?[['↓','12% lower spend',"You’ve spent 12% less than last month.",'Good','green'],['↑','Marketing is 92% used',"You’re close to your marketing budget limit.",'Watch','red'],['◉','Software spend increased','Software expenses are 28% higher than last month.','Info','blue']]:[['↓','Portfolio is up 12.4% this year',"You’ve gained ₹1,35,200 so far.",'Good','green'],['↗','Mutual Funds performing well','Your mutual funds are up 18% this year.','Info','blue'],['↑','Consider diversifying','Stocks are 28% of your portfolio.','Tip','red']];return `<section class="panel insights"><h2>${icon('target')} Insights</h2>${rows.map(r=>`<div class="insight"><span class="insight-symbol ${r[4]}">${r[0]}</span><div><strong>${r[1]}</strong><p>${r[2]}</p></div>${pill(r[3])}</div>`).join('')}</section>`}
function changeChartPeriod(v){const labels=v==='Weekly'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:v==='Yearly'?['2020','2021','2022','2023','2024','2025']:['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];document.querySelectorAll('.chart-bars>div').forEach((el,i)=>{el.style.display=i<labels.length?'':'none';let small=el.querySelector('small');if(small)small.textContent=labels[i]||''})}
function changeBudgetMonth(v){const b=db().budgets.find(b=>b.date?.startsWith(v));if(b){let a=db().budgets;a.splice(a.indexOf(b),1);a.unshift(b);save();render()}else{toast('No budget for this month. Add a budget to get started.')}}
function addBudgetCategory(){if(!db().budgets.length){startEditor('Budget');return}textDialog('Add category','Category name','',v=>{db().budgets[0].categories.push([v,0,0,'more','#99a1b3']);save();render()})}
function budgetCategoryMenu(i){textDialog('Edit category budget','Budget amount (₹)',String(db().budgets[0].categories[i][1]),v=>{if(Number(v)>=0){db().budgets[0].categories[i][1]=Number(v);save();render()}})}
function investmentsPage(){const rows=records();return `<main class="finance-main">${pageHeader('Investment Portfolio','Track your investments, monitor performance, and plan for your financial goals.',`<input type="month" value="2025-04" aria-label="Investment period">${btn(icon('plus')+' Add Investment',"startEditor('Investments')",'primary')}`)}${kpis([['wallet',money(metric(1248500,db().investments.reduce((n,r)=>n+r.current,0))),'Total Portfolio Value','↑ 12.4%','','green','#00c88b'],['chart',money(metric(135200,db().investments.reduce((n,r)=>n+r.current-r.amount,0))),'Total Gain','↑ 12.4%','','green','#4298ff'],['percent',metric('12.4%','—'),'XIRR (Annual)','','','green','#ff99aa'],['clock',money(metric(1113300,db().investments.reduce((n,r)=>n+r.amount,0))),'Invested Amount','']])}<section class="panel portfolio-chart"><div class="panel-head"><h2>${icon('chart')} Portfolio Value</h2><div class="chart-period">${['1M','3M','6M','1Y','All'].map(v=>btn(v,`selectChartPeriod(this,'${v}')`,v==='1Y'?'active':'')).join('')}</div></div><div class="line-chart"><div class="chart-labels"><span>₹16L</span><span>₹12L</span><span>₹8L</span><span>₹4L</span><span>₹0</span></div><svg viewBox="0 0 800 200" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#00bd76" stop-opacity=".17"/><stop offset="1" stop-color="#00bd76" stop-opacity=".02"/></linearGradient></defs><path d="M0 160 C30 180 50 157 80 145 S145 125 175 114 230 76 260 80 315 110 350 95 400 60 430 68 480 90 510 72 550 55 580 58 630 64 660 45 690 20 720 34 755 69 800 48 L800 200H0Z" fill="url(#area)" stroke="none"/><path d="M0 160 C30 180 50 157 80 145 S145 125 175 114 230 76 260 80 315 110 350 95 400 60 430 68 480 90 510 72 550 55 580 58 630 64 660 45 690 20 720 34 755 69 800 48" stroke="#00bd76" fill="none" stroke-width="2"/></svg></div><div class="chart-months">${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].map(m=>`<span>${m}</span>`).join('')}</div></section><section class="panel investments-table"><div class="panel-head"><h2>${icon('wallet')} Your Investments</h2><div class="compact-tabs">${['All','Mutual Funds','Stocks','FD','Gold','Bonds','Others'].map(t=>btn(t,`investmentFilter('${t}')`,(filters.type||'All')===t?'active':'')).join('')}</div></div><table class="data-table"><thead><tr>${['Asset Name','Type','Invested Amount','Current Value','Gain / Loss','Return','Actions'].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr onclick="editRecord('${r.id}')"><td>${nameCell(r.title,r.plan,r.logo)}</td><td>${pill(r.type)}</td><td>${money(r.amount)}</td><td>${money(r.current)}</td><td class="green">+${money(r.current-r.amount)}</td><td class="green">+${((r.current/r.amount-1)*100).toFixed(1)}%</td><td>${ib('more',`event.stopPropagation();recordMenu(event,'${r.id}')`)}</td></tr>`).join('')}</tbody></table>${btn(icon('plus')+' Add Investment',"startEditor('Investments')")}</section></main><section class="finance-side"><div class="panel allocation-panel"><h2>Asset Allocation</h2><div class="allocation-body">${ringChart(money(1248500),'Total Value',[['Mutual Funds',42,'#4298ff'],['Stocks',28,'#00c783'],['FD',12,'#a854ff'],['Gold',8,'#ffbb2f'],['Bonds',6,'#ff5c79'],['Others',4,'#e1e3ea']])}<div class="allocation-legend">${[['Mutual Funds','42%','₹5,24,700','#4298ff'],['Stocks','28%','₹3,49,600','#00c783'],['FD','12%','₹1,49,800','#a854ff'],['Gold','8%','₹99,900','#ffbb2f'],['Bonds','6%','₹74,900','#ff5c79'],['Others','4%','₹49,600','#e1e3ea']].map(r=>`<div><i style="background:${r[3]}"></i><span>${r[0]}</span><small>${r[1]}</small><strong>${r[2]}</strong></div>`).join('')}</div></div></div>${insights('investment')}<div class="panel recent-finance"><div class="panel-head"><h2>${icon('file')} Recent Transactions</h2>${btn('View All '+icon('arrow'),"investmentTransactions()",'text-button')}</div>${[['SIP Investment','5 Apr 2025',10000,'Mutual Fund'],['Bought Shares','12 Mar 2025',25000,'Stock'],['FD Interest Credit','1 Mar 2025',2400,'FD'],['Gold Purchase','15 Feb 2025',50000,'Gold'],['Dividend Received','10 Feb 2025',1800,'Stock']].map(r=>`<div class="recent-row"><span class="transaction-symbol">+</span><div class="row-title"><strong>${r[0]}</strong><small>${r[1]}</small></div><strong>${money(r[2])}</strong>${pill(r[3])}</div>`).join('')}</div></section>`}
function investmentFilter(t){filters.type={All:'','Mutual Funds':'Mutual Fund',Stocks:'Stock',Bonds:'Bond'}[t]??t;render()}function selectChartPeriod(el,v){el.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('active'));el.classList.add('active');document.querySelector('.line-chart svg')?.setAttribute('aria-label','Portfolio value over '+v)}
function investmentTransactions(){document.querySelector('.recent-finance')?.scrollIntoView({behavior:'smooth'});toast('Showing all recorded sample transactions')}
function notesPage(){const n=selected();return `<main class="notes-main">${pageHeader('All Notes','Capture ideas, research, and important information related to your finances and investments.')}<div class="notes-layout"><section class="notes-list">${tabs([['All',24],['Investments',8],['Expenses',5],['Budget',4],['Planning',4],['Ideas',3]])}${records().map(r=>`<button class="note-list-row ${r.id===selectedRecord.Notes?'selected':''}" onclick="selectRecord('${r.id}')">${logoMark(r.logo)}<div><strong>${esc(r.title)}</strong><p>${esc(r.description)}</p><div>${r.tags.map(pill).join(' ')}</div></div><time>${fmtDate(r.date)}</time><span>•••</span></button>`).join('')||'<div class="empty">No notes yet</div>'}</section><section class="note-detail">${n?`<div class="note-detail-toolbar"><span>← &nbsp; All Notes</span><div>${ib('edit',`editRecord('${n.id}')`)}${ib('trash',`removeRecord('${n.id}')`)}${ib('more',`recordMenu(event,'${n.id}')`)}</div></div><div class="note-title">${logoMark(n.logo)}<div><h2>${esc(n.title)}</h2><p>${fmtDate(n.date)} ・ ${esc(n.category)}</p><div>${n.tags.map(pill).join(' ')} ${btn('+',"addRecordTag()",'small-button')}</div></div></div><div class="note-content">${n.content}${n.id==='n0'?`<h3>Comparison with other funds</h3><table class="comparison-table"><tr><th>Fund Name</th><th>Expense Ratio</th><th>5Y Return (CAGR)</th><th>Min SIP</th></tr>${[['HDFC Index Fund','0.20%','14.3%','₹100'],['Nippon India Index','0.27%','13.8%','₹500'],['UTI Nifty Index','0.28%','13.5%','₹500'],['Axis Index Fund','0.32%','13.1%','₹500']].map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')}</table>`:''}<h3>Related Links</h3><div class="related-links">${['HDFC Index Fund - Official Page','Fund Factsheet (PDF)','Detailed Comparison (MoneyControl)'].map((r,i)=>`<a href="${i===2?'https://www.moneycontrol.com':'https://www.hdfcfund.com'}" target="_blank" rel="noopener">${icon('external')}${r}</a>`).join('')}</div></div>`:'<div class="empty">Select a note to read it.</div>'}</section></div></main>`}
function addRecordTag(){textDialog('Add tag','Tag','',v=>{(selected().tags??=[]).push(v);save();render()})}
function meetingIcon(type){return {Advisor:'user',Client:'user',Internal:'note',CA:'bank',Bank:'bank',Team:'users',Interview:'briefcase',Presentation:'board'}[type]||'calendar'}
function miniCalendar(month=3,year=2025,selectedDay=18,handler='pickDate'){let first=new Date(year,month,1),offset=(first.getDay()+6)%7,last=new Date(year,month+1,0).getDate();return `<div class="mini-calendar"><div class="mini-calendar-head">${ib('left',`shiftMiniMonth(-1)`)}<strong>${first.toLocaleDateString('en',{month:'long',year:'numeric'})}</strong>${ib('right',`shiftMiniMonth(1)`)}</div><div class="mini-calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<small>${d}</small>`).join('')}${Array.from({length:35},(_,i)=>{let day=i-offset+1;let date=new Date(year,month,day);return `<button class="${day===selectedDay?'selected ':''}${day<1||day>last?'outside':''}" onclick="${handler}('${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}')">${date.getDate()}</button>`}).join('')}</div></div>`}
let miniMonth=3,miniYear=2025,meetingDate='';
function shiftMiniMonth(n){miniMonth+=n;if(miniMonth<0){miniMonth=11;miniYear--}if(miniMonth>11){miniMonth=0;miniYear++}render()}function pickDate(date){meetingDate=date;filters.date=date;render()}
function meetingsPage(){const m=selected();return `<main class="meetings-main">${pageHeader('Meetings','Plan, track and follow up on important meetings with clients, advisors and stakeholders.')}<div class="meetings-layout"><div class="meeting-left"><div class="meeting-filter-tabs">${tabs([['All',12],['Upcoming',4],['Past',8],['Advisors',4],['Clients',3],['Internal',3]])}</div><div class="meeting-columns"><section class="meeting-calendar"><div class="reference-box">${miniCalendar(miniMonth,miniYear,meetingDate?+meetingDate.slice(-2):18)}<div class="mini-today"><h3>Today <small>2</small></h3>${db().meetings.slice(0,2).map(r=>`<button onclick="selectRecord('${r.id}')"><strong>${esc(r.title.split(' with')[0])}</strong><small>${timeFmt(r.time)} – ${timeFmt(r.end)}</small></button>`).join('')}</div></div><section class="panel meeting-types"><h2>Meeting Types</h2>${['Advisor','Client','Internal','Bank / CA'].map((t,i)=>`<button onclick="setFilter('type','${t==='Bank / CA'?'CA':t}')"><span class="type-icon ${['purple','sent','paid','high'][i]}">${icon(meetingIcon(t))}</span><span>${t}</span><small>${[4,3,3,2][i]}</small></button>`).join('')}</section></section><section class="meeting-list">${viewMode.Meetings==='Calendar'?weekGrid():records().map((r,i,rows)=>`${i===0||rows[i-1].date!==r.date?`<h3>${r.date==='2025-04-18'?'Today':r.date==='2025-04-19'?'Tomorrow':new Date(r.date+'T12:00:00').toLocaleDateString('en',{weekday:'short'})} · ${fmtDate(r.date)}</h3>`:''}<button class="meeting-card ${r.id===selectedRecord.Meetings?'selected':''}" onclick="selectRecord('${r.id}')"><span class="type-icon ${r.type==='Advisor'?'purple':r.type==='Client'?'sent':r.type==='Internal'?'paid':'high'}">${icon(meetingIcon(r.type))}</span><div><strong>${esc(r.title)}</strong><small>${timeFmt(r.time)} – ${timeFmt(r.end)} &nbsp; ${icon(r.location.includes('Meet')?'video':'location')} ${esc(r.location)}</small></div>${pill(r.type)}<span>•••</span></button>`).join('')||'<div class="empty">No meetings match these filters.</div>'}</section></div></div><section class="meeting-inspector">${m?meetingInspector(m):'<div class="empty">Select a meeting</div>'}</section></div></main>`}
function meetingInspector(m){return `<div class="meeting-search"><label class="input-search">${icon('search')}<input placeholder="Search meetings..." oninput="setFilter('search',this.value)"></label>${ib('calendar',"document.querySelector('.mini-calendar').scrollIntoView()")}${ib('filter',"setTab('Upcoming')")}</div><div class="meeting-detail-title"><span class="type-icon purple">${icon(meetingIcon(m.type))}</span><div><h2>${esc(m.title)}</h2><p>${fmtDate(m.date)} · ${timeFmt(m.time)} – ${timeFmt(m.end)}</p></div>${pill(m.type)}${ib('more',`recordMenu(event,'${m.id}')`)}</div><div class="button-row">${btn(icon('video')+' Join Meeting',"joinMeeting()")}${btn(icon('edit')+' Edit',`editRecord('${m.id}')`)}${btn(icon('trash')+' Delete',`removeRecord('${m.id}')`)}</div><div class="detail-card">${rowLine('Date & Time',fmtDate(m.date)+' · '+timeFmt(m.time)+' – '+timeFmt(m.end),'calendar')}${rowLine('Location',`<a href="${esc(m.link||'#')}" target="_blank" rel="noopener">${esc(m.location)} ${icon('external')}</a>`,'location')}${rowLine('Participants',avatars(m.participants)+btn('+ Add',"addParticipant()",'small-button'),'users')}${rowLine('Reminders',`<select aria-label="Reminder" onchange="updateRecord('reminder',this.value)">${['10 minutes before','30 minutes before','1 hour before','1 day before','None'].map(t=>`<option ${m.reminder===t?'selected':''}>${t}</option>`).join('')}</select>`,'bell')}</div><div class="detail-card">${sectionHead(icon('list')+' Agenda',"addChecklist('agenda')")}${checklist(m,'agenda')}<button class="add-agenda" onclick="addChecklist('agenda')">+ &nbsp; Add agenda item...</button></div><div class="detail-card"><div class="panel-head"><h3>${icon('note')} Notes</h3>${btn('Edit',"editText('notes')",'small-button')}</div><p class="meeting-notes">${esc(m.notes||'')}</p></div><div class="detail-card">${sectionHead(icon('attach')+' Attachments ('+(m.attachments||[]).length+')',"uploadToSelected()")}${attachments(m)||'<p>No attachments</p>'}</div>`}
function avatars(names=[]){return `<span class="avatar-group">${names.slice(0,3).map((n,i)=>`<span class="avatar" title="${esc(n)}" style="background:${['#dfe8f7','#215798','#e6eaf3'][i]};color:${i===1?'white':'#233653'}">${n.split(' ').map(x=>x[0]).slice(0,2).join('')}</span>`).join('')}${names.length>3?`<span class="avatar">+${names.length-3}</span>`:''}</span>`}
function addParticipant(){textDialog('Add participant','Name or email','',v=>{(selected().participants??=[]).push(v);save();render()})}
function joinMeeting(){let r=selected();if(r.link){window.open(r.link,'_blank','noopener')}else toast('This meeting has no online meeting link.')}
let calendarOffset=0,calendarDay=2;
function calendarPage(){let ev=selected(),mode=viewMode.Calendar||'Week';return splitPage(pageHeader('April 2025','Plan your meetings, deadlines and stay on top of your schedule.',btn(icon('plus')+' New Event',"startEditor('Calendar')",'primary'))+kpis([['calendar',5,'Meetings this week','↑ 25%','','green','#a0eac7'],['check',8,'Task deadlines','↑ 2','','red'],['calendar',2,'Project deadlines','This month','','muted'],['clock','18h 30m','Scheduled time','↑ 12%']])+`<section class="reference-box calendar-box"><div class="calendar-controls"><div>${ib('left','changeCalendarWeek(-1)')}${ib('right','changeCalendarWeek(1)')}${btn('Today','changeCalendarWeek(0)')}<strong>${mode==='Month'?'April 2025':mode==='Day'?fmtDate('2025-04-'+(21+calendarDay+calendarOffset)):21+calendarOffset+' – '+(27+calendarOffset)+' April 2025'}</strong></div><div><select aria-label="Week display" onchange="document.querySelector('.week-grid')?.classList.toggle('work-week',this.value==='Work week')"><option>Full week</option><option>Work week</option></select>${btn(icon('filter')+' Filter','calendarFilters()')}</div></div>${mode==='Month'?monthGrid():mode==='Agenda'?agendaView():weekGrid(false,mode==='Day')}</section>`,ev?eventInspector(ev):'')}
function hourLabel(h){let hour=Math.floor(h),mins=h%1?'30':'00';return (hour%12||12)+':'+mins+' '+(hour<12?'AM':'PM')}
function weekGrid(tasks=false,day=false){let events=db().events;return `<div class="week-grid ${day?'day-view':''}"><div class="week-grid-head"><span></span>${(day?[calendarDay]:[0,1,2,3,4,5,6]).map(d=>`<button onclick="calendarDay=${d};viewMode.Calendar='Day';render()"><small>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][d]}</small><strong class="${d===2?'today':''}">${21+d+calendarOffset}</strong></button>`).join('')}</div><div class="week-grid-body"><div class="time-labels">${Array.from({length:13},(_,i)=>`<span>${i+8<12?i+8+' AM':i===4?'12 PM':i-4+' PM'}</span>`).join('')}</div>${(day?[calendarDay]:[0,1,2,3,4,5,6]).map(d=>`<div class="week-day" ondblclick="startEditor('Calendar',null,{day:${d}})">${events.filter(e=>e.day===d&&!calendarOffset).map(e=>`<button class="schedule-event ${e.color}" style="top:${(e.hour-8)*49}px;height:${e.duration*49}px" onclick="selectRecord('${e.id}')"><strong>${esc(e.title)}</strong><small>${esc(e.client)}</small><small>${hourLabel(e.hour)} – ${hourLabel(e.hour+e.duration)}</small></button>`).join('')}</div>`).join('')}</div></div>`}
function monthGrid(){const offset=1;return `<div class="month-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<header>${d}</header>`).join('')}${Array.from({length:35},(_,i)=>{let d=i-offset+1;return `<div><small>${d<1?31:d>30?d-30:d}</small>${db().events.filter(e=>+e.date.slice(-2)===d).map(e=>`<button class="schedule-event ${e.color}" onclick="selectRecord('${e.id}')"><strong>${esc(e.title)}</strong><small>${hourLabel(e.hour)}</small></button>`).join('')}</div>`}).join('')}</div>`}
function agendaView(){return `<div class="agenda-view">${[0,1,2,3,4,5,6].map(d=>`<h3>${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][d]} · ${21+d} Apr 2025</h3>${db().events.filter(e=>e.day===d).map(e=>`<button class="agenda-event" onclick="selectRecord('${e.id}')"><span class="event-dot ${e.color}"></span><time>${hourLabel(e.hour)} – ${hourLabel(e.hour+e.duration)}</time><div><strong>${esc(e.title)}</strong><small>${esc(e.client)}</small></div>${avatars(['Aarav','Karan','Priya'])}${icon('more')}</button>`).join('')}`).join('')}</div>`}
function eventInspector(e){return `<div class="event-inspector-head"><strong>Wednesday, 23 Apr 2025</strong>${ib('left','stepEvent(-1)')}${ib('right','stepEvent(1)')}${ib('close','closeInspector()')}</div><div class="detail-card">${miniCalendar(3,2025,23,'selectCalendarDate')}<h3>Today’s events</h3>${db().events.filter(v=>v.day===e.day).map(v=>`<button class="today-event" onclick="selectRecord('${v.id}')"><span class="event-dot ${v.color}"></span><div>${esc(v.title)}<small>${hourLabel(v.hour)} – ${hourLabel(v.hour+v.duration)} &nbsp; ${esc(v.client)}</small></div>${icon('more')}</button>`).join('')}</div><div class="detail-card"><div class="panel-head"><h2>${esc(e.title)}</h2>${btn('Edit',`editRecord('${e.id}')`,'small-button')}</div>${statusSelect(e,['Confirmed','Tentative','Cancelled','Rescheduled'])}${rowLine('',fmtDate(e.date),'calendar')}${rowLine('',hourLabel(e.hour)+' – '+hourLabel(e.hour+e.duration),'clock')}${rowLine('','<a href="https://meet.google.com/abc-defg" target="_blank" rel="noopener">https://meet.google.com/abc-defg</a>','video')}${rowLine('','Online','location')}${rowLine('',esc(e.client),'user')}${rowLine('Project',pill(e.project),'folder')}<p>3 participants</p>${avatars(['Aarav (You)','Karan','Priya'])}<h3 style="margin-top:24px">Description</h3><p>${esc(e.description)}</p></div><div class="detail-card"><h3>Related</h3><button class="related-row" onclick="navigate('Tasks')">${icon('check')} 5 tasks <span>View →</span></button><button class="related-row" onclick="navigate('Invoices')">${icon('invoice')} 0 invoices <span>View →</span></button></div>`}
function changeCalendarWeek(n){calendarOffset=n?calendarOffset+n*7:0;render()}function selectCalendarDate(d){calendarDay=(new Date((d.length===7?d+'-01':d)+'T12:00:00').getDay()+6)%7;viewMode.Calendar='Day';render()}function stepEvent(n){const rows=db().events;let i=rows.findIndex(e=>e.id===selectedRecord.Calendar);selectedRecord.Calendar=rows[(i+n+rows.length)%rows.length]?.id;render()}function calendarFilters(){textDialog('Filter events','Search title or client','',value=>{let e=db().events.find(e=>(e.title+' '+e.client).toLowerCase().includes(value.toLowerCase()));if(e){selectedRecord.Calendar=e.id;render()}else toast('No matching events')})}
function newRecord(p){const base={id:'r'+Date.now(),title:'',date:'2025-04-18',client:'',project:'',status:'Active',description:'',tags:[],attachments:[]};switch(p){case'Projects':return {...base,category:'Website Design',progress:0,amount:0,tracked:'0h 00m',priority:'Medium',logo:'pixel',deliverables:[],done:[],start:'2025-04-18'};case'Clients':return {...base,industry:'',country:'India',location:'',email:'',phone:'',website:'',logo:'nova',projects:0,amount:0,outstanding:0};case'Tasks':return {...base,status:'Todo',priority:'Medium',date:'Today',subtasks:[],done:[],comments:[],estimated:'',tracked:'0h',category:'Design'};case'Invoices':return {...base,title:'INV-'+String(db().invoices.length+1).padStart(3,'0'),client:'Pixel Studio',project:'Website Redesign',date:'2025-04-23',due:'2025-04-30',status:'Draft',tax:0,terms:'Net 7 days',po:'',amount:90000,notes:'Thank you for the opportunity to work on this project. Please make the payment by the due date.',showProject:true,showBank:true,showPayment:true,items:[{title:'UI/UX Design',description:'Homepage + 5 pages',qty:1,rate:60000},{title:'Design Support',description:'Revisions & assets',qty:1,rate:20000},{title:'Project Management',description:'Coordination & meetings',qty:1,rate:10000}],payments:[]};case'Expenses':return {...base,title:'',amount:0,category:'Food & Drinks',payment:'Cash',time:'14:30',location:'',reimbursable:true,billable:false,notes:'',logo:'food',status:'Paid'};case'Budget':return {...base,title:'April 2025',date:'2025-04-01',amount:100000,categories:structuredClone(categories).map(c=>[c[0],c[1],0,c[3],c[4]]),carry:true,applyAll:false,alert:'80%',notes:''};case'Investments':return {...base,title:'',type:'Mutual Fund',provider:'',plan:'Growth Plan',amount:0,current:0,units:'',addCurrent:true,notes:'',logo:'food'};case'Notes':return {...base,title:'',category:'Investments',content:'',logo:'chart'};case'Meetings':return {...base,title:'',type:'Advisor',time:'11:00',end:'12:00',location:'Google Meet',link:'',participants:['Raman Yadav'],agenda:[],done:[],notes:'',reminder:'10 minutes before',invite:true,status:'Upcoming'};case'Calendar':return {...base,title:'',day:2,hour:9.5,duration:1.5,color:'green',status:'Confirmed',time:'09:30',end:'11:00',location:'Online',repeat:'Does not repeat',reminder:'10 minutes before'};default:return base}}
function startEditor(p,record=null,defaults={}){page=p;editorState={page:p,record:record?structuredClone(record):Object.assign(newRecord(p),defaults),existing:!!record};if(p==='Tasks'||p==='Projects'||p==='Clients'){quickType=entity[p];quickModal();return}render();window.scrollTo(0,0)}
function cancelEditor(){editorState=null;render()}
function editorTitle(){return {Invoices:'New Invoice',Expenses:'Add Expense',Budget:'Add Budget',Investments:'Add Investment',Notes:'New Note',Meetings:'New Meeting',Calendar:'New Event'}[page]||'New '+entity[page]}
function field(label,key,type='text',options=[],required=false,placeholder=''){const r=editorState.record;return `<label class="field">${label}${required?' <em>*</em>':''}${type==='select'?`<select name="${key}" ${required?'required':''} onchange="editorChange('${key}',this.value)"><option value="">Select ${label.toLowerCase().replace(' (optional)','')}</option>${options.map(v=>`<option value="${esc(v)}" ${String(r[key])===String(v)?'selected':''}>${esc(v)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${key}" maxlength="${key==='notes'?1000:500}" placeholder="${placeholder||'Add details...'}" oninput="editorChange('${key}',this.value)">${esc(r[key]||'')}</textarea><small class="field-counter">${(r[key]||'').length}/${key==='notes'?1000:500}</small>`:`<input type="${type}" name="${key}" value="${esc(type==='month'?(r[key]||'').slice(0,7):(r[key]??''))}" ${required?'required':''} ${type==='number'?'min="0" step="any"':''} ${type==='text'?'maxlength="120"':''} placeholder="${placeholder}" oninput="editorChange('${key}',${type==='number'?'+this.value':'this.value'})">`}</label>`}
const fieldRow=(...fields)=>`<div class="field-row">${fields.join('')}</div>`;
function formSection(title,body,cls=''){return `<section class="form-section ${cls}"><h2>${title}</h2>${body}</section>`}
function editorHeader(){return `<header class="editor-header"><button class="back-link" onclick="cancelEditor()">${icon('left')} Back to ${page}</button><h1>${editorTitle()}</h1><p>${{Invoices:'Create a professional invoice and send it to your client.',Expenses:'Record a new expense and keep track of your business spending.',Budget:'Create a monthly budget to plan and track your business spending.',Investments:'Record a new investment to track its performance and include it in your portfolio.',Notes:'Capture ideas, research, and important information related to your finances and investments.',Meetings:'Plan and schedule a new meeting with clients, advisors or your team.',Calendar:'Plan your schedule.'}[page]}</p>${['Invoices','Expenses'].includes(page)?btn(icon('file')+' Save as Draft',"saveEditor(true)",'draft-top'):''}</header>`}
function editorFooter(label){return `<div class="editor-footer">${btn('Cancel','cancelEditor()')}<div>${['Notes','Meetings'].includes(page)?btn('Save as Draft','saveEditor(true)'):''}<button class="primary" type="submit" form="record-form">${label||'Create '+entity[page]}</button></div></div>`}
function tagsEditor(){return `<div class="field">Tags (optional)<div class="tag-input">${(editorState.record.tags||[]).map((t,i)=>`<button type="button" class="tag" onclick="removeEditorTag(${i})">${esc(t)} ×</button>`).join('')}${btn('+ Add tag','editorTag()','small-button')}</div></div>`}
function editorPage(){if(!editorState)return '';let r=editorState.record;let form='',preview='';switch(page){case'Invoices':form=invoiceForm();preview=`<div class="preview-header"><h2>5. Preview</h2><div class="segmented">${btn('Desktop',"previewDevice('desktop')",'active')}${btn('Mobile',"previewDevice('mobile')")}</div></div><div id="live-preview">${invoicePaper(r)}</div><div class="button-row invoice-export">${btn(icon('download')+' Download PDF','printInvoice()')}${btn(icon('send')+' Send Invoice','sendInvoice()')}${btn(icon('plus')+' Create Invoice','saveEditor()','primary')}</div>`;break;case'Expenses':form=expenseForm();preview=formSection('5. Receipt',receiptBlock(r))+formSection('6. Preview',expensePreview(r)+editorFooter('Create Expense'));break;case'Budget':form=budgetForm();preview=budgetPreview(r)+editorFooter('Create Budget');break;case'Investments':form=investmentForm();preview=investmentPreview(r);break;case'Notes':form=noteForm();preview=notePreview(r);break;case'Meetings':form=meetingForm();preview=meetingPreview(r);break;case'Calendar':form=eventForm();preview=meetingPreview({...r,type:'Meeting',time:r.time,end:r.end,agenda:[],participants:[]});break;default:return originals.dashboard()};return `<main class="editor-main">${editorHeader()}<form id="record-form" onsubmit="event.preventDefault();saveEditor()">${form}${['Invoices','Expenses','Budget'].includes(page)?'':editorFooter(page==='Notes'?'Save Note':page==='Investments'?'Add Investment':'Create '+entity[page])}</form></main><section class="editor-preview" id="preview-panel">${preview}</section>`}
function editorChange(key,value){editorState.record[key]=value;if(page==='Invoices'&&key==='tax')recalcInvoice();refreshPreview()}
function refreshPreview(){let r=editorState.record,el=document.getElementById('preview-panel');if(!el)return;if(page==='Invoices'){document.getElementById('live-preview').innerHTML=invoicePaper(r);document.querySelectorAll('[data-total]').forEach(e=>e.textContent=money(r.amount))}if(page==='Expenses'){let p=document.querySelector('.expense-preview');if(p)p.outerHTML=expensePreview(r)}if(page==='Notes'){el.innerHTML=notePreview(r)}if(page==='Meetings'||page==='Calendar'){el.innerHTML=meetingPreview(r)}if(page==='Investments'){const p=document.querySelector('.investment-preview');if(p)p.outerHTML=investmentPreviewCard(r)}if(page==='Budget'){const p=document.querySelector('.budget-preview');if(p)p.outerHTML=budgetPreview(r)}}
function invoiceForm(){const r=editorState.record;return formSection('1. Client & Project',fieldRow(field('Client','client','select',db().clients.map(c=>c.title),true),field('Project (optional)','project','select',db().projects.map(p=>p.title))))+formSection('2. Invoice Details',fieldRow(field('Invoice number','title','text',[],true),field('Issue date','date','date',[],true),field('Due date','due','date',[],true),`<label class="field">Currency<select><option>INR (₹)</option><option>USD ($)</option></select></label>`)+fieldRow(field('Payment terms','terms','select',['Net 7 days','Net 15 days','Net 30 days','Due on receipt']),field('PO number (optional)','po'),field('Tax type','tax','select',['0','5','12','18','28'])))+formSection('3. Items',`<div class="invoice-item-head"><span>Item / Description</span><span>Qty</span><span>Rate (₹)</span><span>Amount (₹)</span><span></span></div>${r.items.map((item,i)=>`<div class="invoice-item"><div><input aria-label="Item name" value="${esc(item.title)}" oninput="editInvoiceItem(${i},'title',this.value)"><input class="item-description" aria-label="Item description" value="${esc(item.description||'')}" oninput="editInvoiceItem(${i},'description',this.value)"></div><input aria-label="Quantity" type="number" min="1" value="${item.qty}" oninput="editInvoiceItem(${i},'qty',+this.value)"><input aria-label="Rate" type="number" min="0" value="${item.rate}" oninput="editInvoiceItem(${i},'rate',+this.value)"><span id="item-total-${i}">${money(item.qty*item.rate)}</span>${ib('trash',`removeInvoiceItem(${i})`)}</div>`).join('')}<div class="invoice-item-bottom">${btn(icon('plus')+' Add Item','addInvoiceItem()')}<div><p>Subtotal <strong data-total>${money(r.amount)}</strong></p><p>Tax (${r.tax||0}%) <strong>${money(r.items.reduce((n,v)=>n+v.qty*v.rate,0)*(r.tax||0)/100)}</strong></p><p>Total (INR) <strong data-total>${money(r.amount)}</strong></p></div></div>`)+formSection('4. Notes & Settings',fieldRow(field('Notes to client (optional)','notes','textarea'),`<div class="field invoice-settings">Additional settings${[['showProject','Show project name'],['showPayment','Show payment instructions'],['showBank','Show bank details'],['customMessage','Add custom message']].map(([k,t])=>`<label>${switchControl(r[k],`editorChange('${k}',this.checked)`)} ${t}</label>`).join('')}</div>`))}
function recalcInvoice(){let r=editorState.record;r.amount=r.items.reduce((n,i)=>n+i.qty*i.rate,0)*(1+Number(r.tax||0)/100)}
function editInvoiceItem(i,k,v){editorState.record.items[i][k]=v;recalcInvoice();let e=document.getElementById('item-total-'+i);if(e)e.textContent=money(editorState.record.items[i].qty*editorState.record.items[i].rate);refreshPreview()}function addInvoiceItem(){editorState.record.items.push({title:'New item',description:'',qty:1,rate:0});render()}function removeInvoiceItem(i){editorState.record.items.splice(i,1);recalcInvoice();render()}
function expenseForm(){return formSection('1. Basic Details',fieldRow(field('Description','title','text',[],true,'e.g. Team lunch, software subscription...'),field('Amount','amount','number',[],true))+fieldRow(field('Date','date','date',[],true),field('Time (optional)','time','time'),field('Category','category','select',['Food & Drinks','Software','Travel','Office','Marketing','Utilities','Assets','Domain & Hosting','Learning'],true)))+formSection('2. Project & Client',fieldRow(field('Client','client','select',db().clients.map(c=>c.title)),field('Project (optional)','project','select',db().projects.map(p=>p.title))))+formSection('3. Payment & Location',fieldRow(field('Payment method','payment','select',['Cash','UPI','HDFC Card'],true),`<div class="toggle-field">${switchControl(editorState.record.reimbursable,"editorChange('reimbursable',this.checked)")}<div>Mark as reimbursable<small>Request reimbursement from client later</small></div></div>`)+fieldRow(field('Location (optional)','location'),`<div class="toggle-field">${switchControl(editorState.record.billable,"editorChange('billable',this.checked)")}<div>Billable<small>Include this expense in client billing</small></div></div>`))+formSection('4. Tags & Notes',tagsEditor()+field('Notes (optional)','notes','textarea'))}
function expensePreview(r){return `<div class="expense-preview"><div class="expense-preview-banner">${logoMark('food')}<div><h3>${esc(r.title||'Client Meeting')}</h3><p>${fmtDate(r.date)}, ${timeFmt(r.time)}</p></div><div><strong>${money(r.amount)}</strong>${r.reimbursable?pill('Reimbursable'):''}</div></div>${rowLine('Category',pill(r.category))}${rowLine('Client',nameCell(r.client||'—','',logoFor(r.client)))}${rowLine('Project',esc(r.project||'—'))}${rowLine('Payment method',esc(r.payment))}${rowLine('Location',esc(r.location||'—'))}${rowLine('Tags',(r.tags||[]).map(pill).join(' '))}${rowLine('Notes',esc(r.notes||'—'))}</div>`}
function budgetForm(){const r=editorState.record;return formSection('1. Period & Overall Budget',fieldRow(field('Month','date','month',[],true),field('Total Budget','amount','number',[],true))+'<p class="helper">Set the month and total budget for all categories.</p>')+formSection('2. Categories',`<div class="budget-edit-categories">${r.categories.map((c,i)=>`<div>${nameCell(c[0],'',c[3])}<input type="number" aria-label="${c[0]} budget" min="0" value="${c[1]}" oninput="editBudgetCategory(${i},+this.value)"><span>${Math.round(c[1]/(r.amount||1)*100)}%</span><div class="progress"><i style="width:${Math.min(100,c[1]/(r.amount||1)*100)}%;background:${c[4]}"></i></div>${ib('trash',`removeEditorCategory(${i})`)}</div>`).join('')}</div>${btn(icon('plus')+' Add Category','addEditorCategory()','full dashed')}`)+formSection('3. Alerts & Settings',fieldRow(field('Alert when spending reaches','alert','select',['50%','70%','80%','90%','100%']),`<div class="toggle-field"><div>Carry forward unused budget${switchControl(r.carry,"editorChange('carry',this.checked)")}<small>Carry remaining amount to next month.</small></div></div>`,`<div class="toggle-field"><div>Apply to all clients/projects${switchControl(r.applyAll,"editorChange('applyAll',this.checked)")}<small>Use this budget for all clients and projects.</small></div></div>`)+field('4. Notes (optional)','notes','textarea'))}
function budgetPreview(r){let sum=r.categories.reduce((n,c)=>n+c[1],0);return `<div class="budget-preview"><section class="panel allocation-panel"><div class="panel-head"><h2>Budget Preview</h2>${pill(sum===r.amount?'Balanced':sum>r.amount?'Over budget':'Unallocated')}</div><div class="allocation-body">${ringChart(money(r.amount),'Total Budget',r.categories.map(c=>[c[0],c[1],c[4]]))}<div class="allocation-legend">${r.categories.map(c=>`<div><i style="background:${c[4]}"></i><span>${c[0]}</span><strong>${money(c[1])}</strong><small>${Math.round(c[1]/(r.amount||1)*100)}%</small></div>`).join('')}</div></div></section><section class="panel"><h2>Category Breakdown</h2><table class="data-table"><thead><tr><th>Category</th><th>Budget</th><th>Percentage</th></tr></thead><tbody>${r.categories.map(c=>`<tr><td>${nameCell(c[0],'',c[3])}</td><td>${money(c[1])}</td><td>${Math.round(c[1]/(r.amount||1)*100)}%</td></tr>`).join('')}</tbody></table><div class="info-box">${icon('info')}<div><strong>Tip</strong><p>You can always edit or adjust your budget later. Track your expenses to see how you’re doing against this budget.</p></div></div></section></div>`}
function editBudgetCategory(i,v){editorState.record.categories[i][1]=v;refreshPreview()}function removeEditorCategory(i){editorState.record.categories.splice(i,1);render()}function addEditorCategory(){textDialog('Add category','Category name','',v=>{editorState.record.categories.push([v,0,0,'more','#99a1b3']);render()})}
function investmentRate(r){if(isDemo()&&r.id?.startsWith('a'))return '12.4%';const days=(new Date(r.asOf||new Date().toISOString().slice(0,10))-new Date(r.date))/86400000;if(!(r.amount>0&&r.current>0&&days>0))return '—';return ((Math.pow(r.current/r.amount,365/days)-1)*100).toFixed(1)+'%'}
function investmentForm(){let r=editorState.record;return formSection('1. Investment Details',fieldRow(field('Asset Name','title','text',[],true,'Search or select asset'),field('Type','type','select',['Mutual Fund','Stock','FD','Gold','Bond','ETF','Real Estate','Crypto','Others'],true))+fieldRow(field('Provider / AMC','provider','text',[],false,'e.g. HDFC Mutual Fund'),field('Plan (optional)','plan','select',['Growth Plan','Dividend Plan','Direct Plan','Regular Plan']))+field('Notes (optional)','notes','textarea'))+formSection('2. Investment Amount & Date',fieldRow(field('Invested Amount','amount','number',[],true),field('Investment Date','date','date',[],true),field('Units / Quantity (optional)','units','number')))+formSection('3. Current Value (Optional)',`<div class="current-toggle">${switchControl(r.addCurrent,"editorState.record.addCurrent=this.checked;render()")} Add current value now</div>${r.addCurrent?fieldRow(field('Current Value','current','number'),field('As of Date','asOf','date'))+`<div class="gain-banner"><div><small>Estimated Gain / Loss</small><strong>${money(r.current-r.amount)} &nbsp; <small>(${r.amount?((r.current/r.amount-1)*100).toFixed(1):0}%)</small></strong></div><div><small>XIRR (Approx)</small><strong>${investmentRate(r)}</strong></div></div>`:''}`)+formSection('4. Tags & Notes',tagsEditor()+field('Notes (optional)','additionalNotes','textarea'))}
function investmentPreviewCard(r){return `<section class="panel investment-preview"><div class="panel-head"><h2>Investment Preview</h2>${pill(r.type)}</div>${nameCell(r.title||'Select an asset',(r.provider||'Provider')+' · '+(r.plan||''),r.logo||'chart')}${rowLine('Invested Amount',money(r.amount))}${rowLine('Current Value',money(r.current))}${rowLine('Gain / Loss',`<span class="green">+${money(r.current-r.amount)} (${r.amount?((r.current/r.amount-1)*100).toFixed(1):0}%)</span>`)}${rowLine('XIRR (Approx)',investmentRate(r))}${rowLine('Investment Date',fmtDate(r.date))}${rowLine('Type',esc(r.type))}</section>`}
function investmentPreview(r){return investmentPreviewCard(r)+`<section class="panel type-selector"><h2>Type Selector</h2><div>${[['Mutual Fund','food'],['Stock','stock'],['FD','lock'],['Gold','gold'],['Bond','marketing'],['ETF','chart'],['Real Estate','home'],['Crypto','bitcoin'],['Others','more']].map(([t,ico])=>btn(logoMark(ico)+`<span>${t}</span>`,`editorState.record.type='${t}';render()`,r.type===t?'selected':'')).join('')}</div></section><section class="panel quick-suggestions"><h2>${icon('utilities')} Quick Suggestions</h2>${demoInvestments.slice(0,4).map((s,i)=>`<button onclick="suggestInvestment(${i})">${nameCell(s.title,s.type,s.logo)}${icon('plus')}</button>`).join('')}${btn('+ Add as new investment',"document.querySelector('[name=title]').focus()",'full')}</section>`}
function suggestInvestment(i){let s=demoInvestments[i];Object.assign(editorState.record,{title:s.title,type:s.type,provider:s.provider,plan:s.plan,logo:s.logo});render()}
function noteForm(){let r=editorState.record;return formSection('1. Note Details',fieldRow(field('Title','title','text',[],true,'Enter note title...'),field('Date','date','date'))+fieldRow(field('Category','category','select',['Investments','Expenses','Budget','Planning','Ideas','Income','Tax','Meetings']),tagsEditor()))+formSection('2. Note Content',`<div class="rich-editor"><div class="editor-toolbar"><select aria-label="Text style" onchange="formatNote('formatBlock',this.value)"><option value="p">Paragraph</option><option value="h2">Heading 2</option><option value="h3">Heading 3</option></select>${[['bold','bold'],['italic','italic'],['underline','underline'],['list','insertUnorderedList'],['list','insertOrderedList'],['link','link'],['image','image'],['table','table'],['undo','undo'],['redo','redo']].map(([ico,cmd])=>btn(icon(ico),`formatNote('${cmd}')`,'toolbar-button')).join('')}</div><div id="note-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Note content" data-placeholder="Start writing your note..." oninput="editorChange('content',this.innerHTML)">${r.content||''}</div><small>${(r.content||'').replace(/<[^>]*>/g,'').length}/5000</small></div>`)+formSection('3. Attachments (optional)',`<button class="upload-zone" onclick="uploadEditorFiles()" type="button">${icon('upload')}<strong>Upload files or drag and drop</strong><small>PDF, DOC, Images (Max 10MB each)</small></button>${editorAttachments()}`)}
function notePreview(r){return `<article class="panel note-form-preview">${logoMark(r.category==='Investments'?'chart':'note')}<h1>${esc(r.title||'New Note')}</h1><p>${fmtDate(r.date)} ・ ${esc(r.category)}</p><div>${(r.tags||[]).map(pill).join(' ')}</div><div class="note-content">${r.content||'<p>Your note content will appear here.</p>'}</div><h3>Attachments (${(r.attachments||[]).length})</h3>${editorAttachments()}</article>`}
function formatNote(cmd,value){let editor=document.getElementById('note-editor');if(!editor)return;if(cmd==='link'){textDialog('Insert link','URL','https://',v=>{editor.focus();document.execCommand('createLink',false,v);editorChange('content',editor.innerHTML)});return}if(cmd==='image'){chooseFiles(files=>{editor.focus();files.filter(f=>f.mime?.startsWith('image/')).forEach(f=>document.execCommand('insertHTML',false,'<img data-file-id="'+f.id+'" src="'+f.url+'" alt="'+esc(f.name)+'">'));editorChange('content',editor.innerHTML)});return}if(cmd==='table'){editor.focus();document.execCommand('insertHTML',false,'<table><tr><td>Column 1</td><td>Column 2</td></tr><tr><td>Value</td><td>Value</td></tr></table>');editorChange('content',editor.innerHTML);return}editor.focus();document.execCommand(cmd,false,value);editorChange('content',editor.innerHTML)}
function meetingForm(){let r=editorState.record;return formSection('1. Meeting Details',fieldRow(field('Title','title','text',[],true,'e.g. Portfolio Review with Financial Advisor'),field('Meeting Type','type','select',['Advisor','Client','Internal','Bank','CA','Interview','Presentation','Team','Other'],true))+fieldRow(field('Date & Time','date','date',[],true),field('Start time','time','time',[],true),field('End time','end','time',[],true),`<label class="toggle-field">${switchControl(r.allDay,"editorChange('allDay',this.checked)")} All day</label>`)+fieldRow(field('Location','location','select',['Google Meet','Teams','Phone Call','Office (Thane)','Office (Mumbai)','Other'],true),field('Meeting Link (optional)','link','url',[],false,'https://meet.google.com/abc-defg-hij')))+formSection('2. Participants',`<label class="input-search full">${icon('search')}<input placeholder="Search or invite by name or email..." onkeydown="if(event.key==='Enter'){event.preventDefault();addEditorParticipant(this.value);this.value=''}"></label><div class="participant-cards">${r.participants.map((n,i)=>`<span>${avatars([n])}<span>${esc(n)}<small>${i===0?'Organizer':i===1?'Financial Advisor':'Client'}</small></span>${btn('×',`editorState.record.participants.splice(${i},1);render()`,'more')}</span>`).join('')}</div>`)+formSection('3. Agenda (optional)',`<div class="agenda-editor">${r.agenda.map((a,i)=>`<div>${icon('grip')}<input type="checkbox" class="check" ${(r.done||[]).includes(i)?'checked':''} onchange="editorToggleAgenda(${i},this.checked)"><input aria-label="Agenda item" value="${esc(a)}" oninput="editorState.record.agenda[${i}]=this.value;refreshPreview()">${ib('trash',`editorState.record.agenda.splice(${i},1);render()`)}</div>`).join('')}<button type="button" onclick="editorAgenda()">+ &nbsp; Add agenda item...</button></div>`)+formSection('4. Notes (optional)',field('','notes','textarea'))+formSection('5. Attachments (optional)',`<button type="button" class="upload-zone" onclick="uploadEditorFiles()">${icon('upload')}<strong>Upload files or drag and drop</strong><small>PDF, DOC, Excel, Images (Max 10MB each)</small></button>${editorAttachments()}`)}
function meetingPreview(r){return `<article class="panel meeting-form-preview"><div class="panel-head"><h2>Preview</h2>${btn('View in Calendar '+icon('arrow'),"cancelEditor();navigate('Calendar')",'small-button')}</div><div class="meeting-preview-banner"><span class="type-icon purple">${icon(meetingIcon(r.type))}</span><div><h3>${esc(r.title||'Meeting title')}</h3>${pill((r.type||'Meeting')+' Meeting')}</div></div>${rowLine('',fmtDate(r.date),'calendar')}${rowLine('',timeFmt(r.time)+' – '+timeFmt(r.end),'clock')}${rowLine('',esc(r.location||'Online'),'location')}${rowLine('',avatars(r.participants||[]),'users')}${rowLine('',r.reminder||'10 minutes before','bell')}${rowLine('',(r.agenda||[]).length+' agenda items','note')}<hr><h3>Agenda</h3><ol>${(r.agenda||[]).map(a=>`<li>${esc(a)}</li>`).join('')}</ol><hr><h3>Attachments</h3>${editorAttachments()||'<p>No attachments</p>'}<div class="info-box">${icon('info')}<span>A calendar invite with meeting link will be sent to all participants.</span>${switchControl(r.invite!==false,"editorChange('invite',this.checked)")}</div></article>`}
function eventForm(){return formSection('Event Details',fieldRow(field('Title','title','text',[],true),field('Calendar','color','select',['blue','green','purple','red','yellow','gray']))+fieldRow(field('Date','date','date',[],true),field('Start time','time','time',[],true),field('End time','end','time',[],true))+field('Repeat','repeat','select',['Does not repeat','Daily','Weekly','Monthly'])+fieldRow(field('Location / Meeting link','location'),field('Project','project','select',db().projects.map(p=>p.title)))+field('Description','description','textarea')+field('Reminders','reminder','select',['10 minutes before','30 minutes before','1 hour before','1 day before']))}
function editorTag(){textDialog('Add tag','Tag','',v=>{(editorState.record.tags??=[]).push(v);render()})}function removeEditorTag(i){editorState.record.tags.splice(i,1);render()}function editorAttachments(){return (editorState.record.attachments||[]).map((a,i)=>`<div class="attachment-row">${logoMark('file','small')}<div><strong>${esc(a.name)}</strong><small>${a.size||'Sample file'}</small></div>${ib('close',`editorState.record.attachments.splice(${i},1);render()`)}</div>`).join('')}function uploadEditorFiles(){chooseFiles(files=>{(editorState.record.attachments??=[]).push(...files);render()})}function addEditorParticipant(v){if(v.trim()){editorState.record.participants.push(v.trim());render()}}function editorAgenda(){textDialog('Add agenda item','Agenda item','',v=>{editorState.record.agenda.push(v);render()})}function editorToggleAgenda(i,v){let r=editorState.record;r.done=v?[...new Set([...r.done,i])]:r.done.filter(d=>d!==i);refreshPreview()}function previewDevice(mode){document.getElementById('live-preview').classList.toggle('mobile-preview',mode==='mobile')}
function saveEditor(draft=false){if(!editorState)return;const form=document.getElementById('record-form');if(!draft&&form&&!form.reportValidity())return;let r=editorState.record;if(!r.title.trim()){toast('Please enter a title');return}if(['Expenses','Investments','Budget'].includes(page)&&!draft&&!(r.amount>0)){toast('Enter an amount greater than zero');return}if(page==='Notes'&&!draft&&!r.content.replace(/<[^>]*>/g,'').trim()){toast('Please add some note content');return}if(page==='Meetings'&&!r.allDay&&!draft&&r.end<=r.time){toast('End time must be after start time');return}if(page==='Budget'&&r.date.length===7)r.date+='-01';if(page==='Calendar'){let [h,m]=r.time.split(':').map(Number),[eh,em]=r.end.split(':').map(Number);r.hour=h+m/60;r.duration=eh+em/60-r.hour;if(r.duration<=0){toast('End time must be after start time');return}r.day=(new Date(r.date+'T12:00:00').getDay()+6)%7}if(page==='Invoices')recalcInvoice();if(draft)r.status='Draft';r.updatedAt=new Date().toISOString();const rows=db()[pageKey[page]],i=rows.findIndex(x=>x.id===r.id);if(i>=0)rows[i]=r;else rows.push(r);selectedRecord[page]=r.id;if(page==='Budget'&&i<0){rows.splice(rows.indexOf(r),1);rows.unshift(r)}editorState=null;syncDashboard();save();render();toast(entity[page]+(draft?' saved as draft':' saved successfully'))}
function syncDashboard(){const d=data(),p=db();d.tasks=p.tasks.filter(t=>t.date==='Today').map(t=>[t.title,t.client,t.project,t.priority,t.isDone||t.status==='Done']);d.projects=p.projects.filter(p=>p.status==='Active').map(p=>[p.title,p.client,p.progress,shortDate(p.date),p.logo]);d.clients=p.clients.slice(0,4).map(c=>[c.title,c.projects+' projects',money(c.amount),c.logo]);d.invoices=p.invoices.slice(0,3).map(i=>[i.title,i.client,money(i.amount),i.status,shortDate(i.date)]);d.investments=p.investments.slice(0,3).map(i=>[i.title,money(i.current),((i.current/i.amount-1)*100).toFixed(1)+'%'])}
function quickModal(){originals.openQuick(entity[page]);let form=document.getElementById('quick-form'),r=editorState.record;form.querySelector('[name=title]').value=r.title||'';form.querySelector('[name=description]').value=r.description||'';if(page==='Clients'){form.querySelector('.field-row').outerHTML=fieldRow(field('Email','email','email'),field('Phone','phone'))+fieldRow(field('Industry','industry'),field('Country','country','select',['India','USA','UAE','UK','Other']))}else if(page==='Projects'){form.querySelector('.field-row').insertAdjacentHTML('afterend',fieldRow(field('Budget','amount','number'),field('Deadline','date','date')))}else{form.querySelector('.field-row').insertAdjacentHTML('afterend',fieldRow(field('Status','status','select',['Todo','In Progress','Review','Blocked','Done']),field('Estimated time','estimated')))}form.onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);for(const [k,v] of f)if(v)r[k]=k==='amount'?+v:v;r.priority=priority;r.client=f.get('client')||r.client||'Personal';r.project=f.get('project')||r.project||'—';r.date=f.get('date')||r.date;const another=document.getElementById('create-another').checked;saveEditor();if(another)startEditor(page)};document.querySelector('.modal footer button.primary').textContent=editorState.existing?'Save '+entity[page]:'Add '+entity[page];document.querySelector('.modal header button').onclick=()=>{editorState=null;closeOverlay()};document.querySelector('.modal footer button:not(.primary)').onclick=()=>{editorState=null;closeOverlay()}}
const originalSubmitQuick=submitQuick;
toggleTask=function(i,v){const title=data().tasks[i]?.[0];let record=db().tasks.find(t=>t.title===title);if(record){record.isDone=v;record.status=v?'Done':'Todo';}if(data().tasks[i])data().tasks[i][4]=v;save();render()};
submitQuick=function(e){if(editorState){e.preventDefault();return}e.preventDefault();let type=quickType,p=Object.keys(entity).find(k=>entity[k]===type);if(!p)return;let f=new FormData(e.target),r=newRecord(p);for(const[k,v]of f)if(v)r[k]=k==='amount'?+v:v;r.title=f.get('title').trim();if(!r.title)return;r.priority=priority;r.client=f.get('client')||'Personal';r.project=f.get('project')||'—';if(p==='Notes')r.content='<p>'+esc(f.get('description')||'')+'</p>';if(p==='Meetings')r.agenda=[];let another=document.getElementById('create-another').checked;db()[pageKey[p]].push(r);syncDashboard();save();render();if(another)originals.openQuick(type);toast(type+' created successfully')};
openQuick=function(type='Task'){if(editorState){editorState=null;render()}originals.openQuick(type)};
createWorkspace=function(e){e.preventDefault();const name=new FormData(e.target).get('workspaceName').trim();if(!name)return;const id='ws-'+Date.now();state.workspaces.push({id,name,data:Object.fromEntries(Object.keys(seed).map(k=>[k,[]]))});initProduct();switchWorkspace(id);toast('Workspace created')};switchWorkspace=function(id){editorState=null;initProduct();originals.switchWorkspace(id);filters={};window.detailTab='Overview';render()};
detail=function(type,i){const target=Object.keys(entity).find(p=>entity[p]===type);if(target){let row=db()[pageKey[target]][i];if(row){goRecord(target,row.id);return}}originals.detail(type,i)};
searchAll=function(v){if(!v.trim())return;let results=[];for(const[p,key]of Object.entries(pageKey)){for(const r of db()[key])if((r.title+' '+(r.description||'')).toLowerCase().includes(v.toLowerCase()))results.push([p,r]);}document.getElementById('overlay').innerHTML=`<div class="global-results">${results.slice(0,12).map(([p,r])=>btn(icon(icons[navs.indexOf(p)]||'file')+`<div><strong>${esc(r.title)}</strong><small>${entity[p]}</small></div>`,`goRecord('${p}','${r.id}')`)).join('')||'<p>No results found</p>'}</div>`};
document.addEventListener('click',e=>{if(!e.target.closest('.context-menu')&&!e.target.closest('.icon-btn'))document.querySelector('.context-menu')?.remove()});
/* Ensure buttons inside record forms do not accidentally submit the form. */
const buttonObserver=new MutationObserver(()=>{document?.querySelectorAll('button:not([type])').forEach(b=>b.type='button')});buttonObserver.observe(document.getElementById('app'),{childList:true,subtree:true});
render();

async function hydrateReceiptImages(){for(const image of document.querySelectorAll('img[data-file-id]')){if(!image.dataset.fileId)continue;try{const url=await window.MonoFiles.url({id:image.dataset.fileId});if(url&&image.isConnected)image.src=url}catch{}}}
const renderWithFileSupport=render;render=function(){renderWithFileSupport();hydrateReceiptImages()};

document.addEventListener('dragover',event=>{if(event.target.closest('.upload-zone')){event.preventDefault();event.dataTransfer.dropEffect='copy'}});
document.addEventListener('drop',async event=>{if(!event.target.closest('.upload-zone'))return;event.preventDefault();const files=[];for(const file of event.dataTransfer.files){if(file.size>10*1024*1024){toast(file.name+' exceeds 10 MB');continue}try{files.push(await window.MonoFiles.put(file))}catch{toast('File could not be stored')}}if(!files.length)return;const record=editorState?.record||selected();if(!record)return;if(page==='Expenses')record.receipt=files[0];else (record.attachments??=[]).push(...files);if(!editorState)save();render()});

const routeNavigate=navigate;navigate=function(p){routeNavigate(p);if(navs.includes(p))history.pushState({page:p},'', '#/'+p.toLowerCase());document.title='mono. — '+p};
window.addEventListener('popstate',()=>{const target=navs.find(n=>n.toLowerCase()===location.hash.replace('#/',''));if(target){page=target;editorState=null;filters={};render()}});
const initialPage=navs.find(n=>n.toLowerCase()===location.hash.replace('#/',''));if(initialPage){page=initialPage;render()}
